function villagePlan(v){
 const k=v.a+','+v.b;if(villagePlans.has(k))return villagePlans.get(k);
 const p=[],b=v.base,P=(x,z,w,d)=>planRect(p,x,b,z,w,d,'path');
 P(-22,-1,45,3);P(-1,-22,3,45);P(-21,-12,20,1);P(-22,10,21,1);P(7,-5,3,4);P(7,2,2,2);P(-5,2,3,1);
 for(const [x,z] of [[-18,-2],[-10,-2],[-18,2],[-10,2],[19,2],[18,-2]])P(x,z,1,1);
 buildHouse(p,-21,-8,b,'south','plain',0);buildHouse(p,-13,-8,b,'south','lib',0);
 buildHouse(p,-21,-18,b,'south','plain',4);buildHouse(p,-13,-18,b,'south','shep',6);
 buildHouse(p,-21,3,b,'north','plain',1);buildHouse(p,-13,3,b,'north','plain',3);
 buildHouse(p,16,3,b,'north','plain',2);buildHouse(p,15,-8,b,'south','plain',5);
 buildChurch(p,b);buildSmith(p,b);buildWell(p,b,-4,-5);buildStall(p,b);
 buildFarm(p,-22,11,b,9,7);buildFarm(p,-12,11,b,9,7);
 for(const [x,z,n] of [[-22,5,1],[-22,6,2],[-22,8,1],[-16,9,1],[-6,9,2],[-4,19,1],[-3,19,2],[-14,19,1],[-13,19,1],[-22,19,2],[14,-10,2],[14,-9,1],[22,12,1],[22,13,2],[14,13,1]])for(let i=1;i<=n;i++)planAdd(p,x,b+i,z,'hay_bale');
 planRect(p,15,b+1,15,6,2,'hay_bale');planRect(p,16,b+2,15,4,2,'hay_bale');planRect(p,17,b+3,15,2,2,'hay_bale');
 for(const [x,z] of [[-14,-2],[-6,-2],[5,-2],[14,-2],[-14,2],[-6,2],[14,2],[2,-10],[-2,10],[2,10]]){planAdd(p,x,b+1,z,'fence');planAdd(p,x,b+2,z,'fence');planAdd(p,x,b+3,z,'torch');}
 const out=p.map(([x,y,z,t,m])=>[x+v.cx,y,z+v.cz,t,m]);
 out.jobs=[{prof:'farmer',x:-8,z:10},{prof:'librarian',x:-10,z:-2},{prof:'blacksmith',x:8,z:7},{prof:'cleric',x:8,z:-9},{prof:'butcher',x:19,z:2},{prof:'leatherworker',x:18,z:-2},{prof:'shepherd',x:-10,z:2},{prof:'mason',x:-4,z:3}];
 villagePlans.set(k,out);return out;
}
function villageChestKey(x,y,z){return `${x},${y},${z}`;}
const villageChestKeys=new Set();
const cropKeys=new Set();
const saplingKeys=new Set();


function buildFairyTreeHomesForChunk(cx,cz,set){
 if(worldType==='superflat')return;
 const minX=cx*CS,minZ=cz*CS,maxX=minX+15,maxZ=minZ+15;
 const ax0=Math.floor((minX-12)/BIOME_SIZE),ax1=Math.floor((maxX+12)/BIOME_SIZE);
 const az0=Math.floor((minZ-12)/BIOME_SIZE),az1=Math.floor((maxZ+12)/BIOME_SIZE);
 const offsets=[[88,92],[278,108],[188,292]];
 for(let a=ax0;a<=ax1;a++)for(let b=az0;b<=az1;b++){
  if(biomeCell(a,b)!=='fairy_forest')continue;
  for(let hi=0;hi<offsets.length;hi++){
   const hx=a*BIOME_SIZE+offsets[hi][0],hz=b*BIOME_SIZE+offsets[hi][1];
   if(hx<minX-8||hx>maxX+8||hz<minZ-8||hz>maxZ+8)continue;
   const base=heightAt(hx,hz),wood=hash2(a*7+hi,b*11-hi,801)<.5?'pink':'purple',alt=wood==='pink'?'purple':'pink';
   const put=(wx,wy,wz,type,onlyAir=false)=>set(wx-minX,wy,wz-minZ,ID[type],onlyAir);
   // A thick four-block trunk lifts each house into its canopy.
   for(let y=1;y<=12;y++)for(let dx=-1;dx<=0;dx++)for(let dz=-1;dz<=0;dz++)put(hx+dx,base+y,hz+dz,wood+'_log');
   // Broad layered crown surrounding the treehouse.
   for(let layer=0;layer<7;layer++){
    const yy=base+9+layer,r=[4,5,5,5,4,3,2][layer];
    for(let dx=-r;dx<=r;dx++)for(let dz=-r;dz<=r;dz++){
     if(dx*dx+dz*dz>r*r+1)continue;
     if(dx>=-1&&dx<=0&&dz>=-1&&dz<=0&&yy<=base+12)continue;
     put(hx+dx,yy,hz+dz,((dx+dz+layer)%5===0?alt:wood)+'_leaves',true);
    }
   }
   // Raised platform, compact home, windows, and a leaf roof.
   const floorY=base+9;
   for(let dx=-4;dx<=4;dx++)for(let dz=-4;dz<=4;dz++)put(hx+dx,floorY,hz+dz,wood+'_planks');
   for(let y=10;y<=13;y++)for(let dx=-3;dx<=3;dx++)for(let dz=-3;dz<=3;dz++){
    if(Math.abs(dx)!==3&&Math.abs(dz)!==3)continue;
    const isCorner=Math.abs(dx)===3&&Math.abs(dz)===3;
    let block=isCorner?wood+'_log':((dx+dz+y)%4===0?'glass':wood+'_planks');
    if(dx===0&&dz===3&&(y===10||y===11))continue;
    put(hx+dx,base+y,hz+dz,block);
   }
   put(hx,base+10,hz+3,'door_bottom');put(hx,base+11,hz+3,'door_top');
   for(let dx=-4;dx<=4;dx++)for(let dz=-4;dz<=4;dz++){
    if(dx*dx+dz*dz>18)continue;
    put(hx+dx,base+14,hz+dz,((dx+dz)%3===0?alt:wood)+'_leaves',true);
   }
   put(hx-2,base+10,hz-1,'fairy_lantern');put(hx+2,base+10,hz-1,'fairy_lantern');
   put(hx-1,base+10,hz,'shelf');put(hx+1,base+10,hz,'couch');
   put(hx,base+10,hz-1,'chair');
  }
 }
}

function waterTopAt(x,z){if(villageAt(x,z))return null;const r=riverInfo(x,z);if(r)return r.core?RIVER_LEVEL:null;const l=lakeAt(x,z);return l&&l.q<1?l.level:null;}
function genChunk(cx,cz){
 const ch={cx,cz,data:new Uint8Array(256*HT),meta:new Uint8Array(256*HT),meshes:[],torches:[],top:0};
 const d=ch.data;
 const set=(lx,y,lz,id,onlyAir)=>{
  const yy=y-MIN_Y;
  if(lx<0||lx>15||lz<0||lz>15||yy<0||yy>=HT)return;
  const i=yy*256+lz*16+lx;
  if(onlyAir&&d[i])return;
  d[i]=id;if(yy>ch.top)ch.top=yy;
 };
 const H=[],V=[],W=[],SD=[];
 for(let lz=0;lz<16;lz++)for(let lx=0;lx<16;lx++){
  const wx=cx*16+lx,wz=cz*16+lz,info=terrainInfo(wx,wz),vil=villageAt(wx,wz);
  const river=riverInfo(wx,wz),lake=river?null:lakeAt(wx,wz);
  let h=info.h,kind=info.biome==='desert'?'sand':(info.mountain>.72&&h>17)?'stone':'grass';
  if(river){
   // Sand is limited to the channel and its immediate waterline; the rest of
   // the bank stays grass and rises smoothly back into the surrounding terrain.
   kind=(river.core||river.shore)?'sand':'grass';
   h=river.core?RIVER_LEVEL-2:Math.max(RIVER_LEVEL,Math.round(RIVER_LEVEL+1+(info.h-RIVER_LEVEL-1)*river.t));
  }else if(lake){
   if(lake.q<1){kind='sand';h=lake.level-1-Math.floor((1-lake.q)*2);}
   else{
    kind=lake.q<1.1?'sand':'grass';
    h=Math.round(lake.level+(info.h-lake.level)*sstep(1,1.35,lake.q));
   }
  }
  V[lz*16+lx]=!!vil;
  if(vil){
   if(vil.d<=22)h=vil.v.base;
   else{const t=(26-vil.d)/4;h=Math.round(h*(1-t)+vil.v.base*t);}
   kind='grass';
  }
  W[lz*16+lx]=!vil&&((river&&river.core)||(lake&&lake.q<1));
  H[lz*16+lx]=h;SD[lz*16+lx]=kind==='sand'&&!vil;
  const surfaceType=kind==='grass'&&!vil?(info.biome==='jungle'?'jungle_grass':info.biome==='spruce'?'spruce_grass':info.biome==='fairy_forest'?'fairy_grass':'grass'):kind;
  const soilType=kind==='grass'&&!vil?(info.biome==='jungle'?'jungle_dirt':info.biome==='spruce'?'spruce_dirt':info.biome==='fairy_forest'?'fairy_dirt':'dirt'):'dirt';
  for(let y=MIN_Y;y<=h;y++){
   const top=y===h,under=y>=h-3;
   set(lx,y,lz,(W[lz*16+lx]&&y>=h-1&&vnoise(wx/5,wz/5,331)>.56)?ID.clay:top?ID[surfaceType]:under?(kind==='stone'?ID.stone:kind==='sand'?ID.sand:ID[soilType]):ID.stone);
  }
  if(river&&river.core)for(let y=h+1;y<=RIVER_LEVEL;y++)set(lx,y,lz,ID.water);
  if(lake&&lake.q<1)for(let y=h+1;y<=lake.level;y++)set(lx,y,lz,ID.water);
 }
 // Caves stay safely underground, leaving at least a three-block roof so
 // they never clip through hillsides or open into the surface.
 for(let lz=0;lz<16;lz++)for(let lx=0;lx<16;lx++){
  const col=lz*16+lx;if(V[col]||W[col])continue;
  const wx=cx*16+lx,wz=cz*16+lz,surface=H[col];
  for(let y=MIN_Y+2;y<=surface-3;y++){
   if(!caveAt(wx,y,wz,surface))continue;
   const i=(y-MIN_Y)*256+col,id=d[i];
   if(id===ID.stone||DIRT_TYPES.has(TYPES[id])||GRASS_TYPES.has(TYPES[id]))d[i]=0;
  }
 }
 // Rare ravines cut deep, open canyons through the surface.
 for(let lz=0;lz<16;lz++)for(let lx=0;lx<16;lx++){
  const col=lz*16+lx;if(V[col]||W[col])continue;
  const wx=cx*16+lx,wz=cz*16+lz,rav=ravineAt(wx,wz);if(!rav)continue;
  const top=H[col],bottom=Math.max(MIN_Y+5,top-Math.round(9+rav.strength*30));
  for(let y=bottom;y<=top;y++){
   const i=(y-MIN_Y)*256+col,id=d[i];
   if(id===ID.stone||DIRT_TYPES.has(TYPES[id])||GRASS_TYPES.has(TYPES[id])||id===ID.sand)d[i]=0;
  }
 }
 // Ore veins replace remaining stone, exposing plenty of ore along cave walls.
 const rng=mulberry(Math.imul(cx,73856093)^Math.imul(cz,19349663)^Math.imul(worldSeed+1,83492791));
 const vein=(id,n,size,y0,y1)=>{
  for(let k=0;k<n;k++){
   let x=rng()*16|0,y=y0+(rng()*(y1-y0+1)|0),z=rng()*16|0;
   const sz=size-1+(rng()*3|0);
   for(let s=0;s<sz;s++){
    if(x>=0&&x<16&&z>=0&&z<16&&y>=MIN_Y&&y<MIN_Y+HT){
     const i=(y-MIN_Y)*256+z*16+x;if(d[i]===ID.stone)d[i]=id;
    }
    const a=rng()*3|0,dir=rng()<.5?-1:1;
    if(a===0)x+=dir;else if(a===1)y+=dir;else z+=dir;
   }
  }
 };
 vein(ID.coal_ore,19,7,-23,8);
 vein(ID.iron_ore,11,5,-23,-2);
 vein(ID.diamond_ore,2,3,-23,-13);
 vein(ID.rhinestone_ore,3,4,-23,-8);
 if(terrainInfo(cx*16+8,cz*16+8).mountain>.35)vein(ID.emerald_ore,3,1,-4,28);else if(rng()<.35)vein(ID.emerald_ore,1,1,-23,-6);
 // Tree species and density follow the biome. Jungle canopies are broad,
 // spruce crowns are conical, and fairy trees grow tall with thick pastel trunks.
 if(worldType!=='superflat')for(let lz=2;lz<14;lz++)for(let lx=2;lx<14;lx++){
  const wx=cx*16+lx,wz=cz*16+lz,info=terrainInfo(wx,wz),biome=info.biome;
  if(biome==='desert'||lakeAt(wx,wz)||riverInfo(wx,wz)||villageAt(wx,wz)||wx*wx+(wz-5)*(wz-5)<100)continue;
  const chance=biome==='jungle'?.095:biome==='spruce'?.065:biome==='fairy_forest'?.055:info.mountain>.45?.003:info.forest>.55?.04:info.forest>.43?.018:.006;
  if(hash2(wx,wz,7)>=chance)continue;
  const h=H[lz*16+lx],topId=d[(h-MIN_Y)*256+lz*16+lx];
  if(!GRASS_TYPES.has(TYPES[topId]))continue;
  const roll=hash2(wx,wz,9);
  const species=biome==='jungle'?'jungle':biome==='spruce'?'spruce':biome==='fairy_forest'?(roll<.5?'pink':'purple'):roll<.58?'oak':roll<.80?'birch':'spruce';
  const logType=species==='oak'?'log':species+'_log',leafType=species==='oak'?'leaves':species+'_leaves';
  const th=species==='pink'||species==='purple'?10+(hash2(wx,wz,10)*4|0):species==='jungle'?8+(hash2(wx,wz,10)*5|0):species==='spruce'?6+(hash2(wx,wz,10)*4|0):species==='birch'?5+(hash2(wx,wz,10)*3|0):4+(hash2(wx,wz,10)*3|0);
  if(species==='pink'||species==='purple'){
   for(let y=1;y<=th;y++)for(let dx=-1;dx<=0;dx++)for(let dz=-1;dz<=0;dz++)set(lx+dx,h+y,lz+dz,ID[logType]);
   for(let layer=0;layer<7;layer++){
    const yy=h+th-4+layer,radius=[2,3,4,4,4,3,2][layer];
    for(let dx=-radius;dx<=radius;dx++)for(let dz=-radius;dz<=radius;dz++){
     if(dx*dx+dz*dz>radius*radius+1)continue;
     if(dx>=-1&&dx<=0&&dz>=-1&&dz<=0&&yy<=h+th)continue;
     const lt=((dx+dz+layer+Math.floor(hash2(wx,wz,110+layer)*3))%4===0)?(species==='pink'?'purple_leaves':'pink_leaves'):leafType;
     set(lx+dx,yy,lz+dz,ID[lt],true);
    }
   }
  }else{
   for(let y=1;y<=th;y++)set(lx,h+y,lz,ID[logType]);
   if(species==='spruce'){
    for(let layer=0;layer<5;layer++){
     const yy=h+th-3+layer,radius=layer===0?1:layer===1?2:layer===2?3:layer===3?2:1;
     for(let dx=-radius;dx<=radius;dx++)for(let dz=-radius;dz<=radius;dz++){
      if(Math.abs(dx)+Math.abs(dz)>radius*2+1)continue;
      if(dx===0&&dz===0&&yy<=h+th)continue;
      set(lx+dx,yy,lz+dz,ID[leafType],true);
     }
    }
    set(lx,h+th+2,lz,ID[leafType],true);
   }else{
    const canopyRadius=species==='jungle'?3:2;
    for(let dy=th-2;dy<=th+2;dy++){
     const radius=(dy===th+2)?1:canopyRadius;
     for(let dx=-radius;dx<=radius;dx++)for(let dz=-radius;dz<=radius;dz++){
      if(Math.abs(dx)+Math.abs(dz)>radius*2+1)continue;
      if(dx===0&&dz===0&&dy<=th)continue;
      set(lx+dx,h+dy,lz+dz,ID[leafType],true);
     }
    }
    set(lx,h+th+3,lz,ID[leafType],true);
   }
  }
 }
 // Cacti are scattered sparingly across open desert sand.
 if(worldType!=='superflat')for(let lz=1;lz<15;lz++)for(let lx=1;lx<15;lx++){
  const wx=cx*16+lx,wz=cz*16+lz;
  if(biomeAt(wx,wz)!=='desert'||hash2(wx,wz,710)>.0035)continue;
  const h=H[lz*16+lx],idx=(h-MIN_Y)*256+lz*16+lx;
  if(d[idx]!==ID.sand||d[idx+256])continue;
  const height=1+(hash2(wx,wz,711)*3|0);
  for(let n=1;n<=height;n++)set(lx,h+n,lz,ID.cactus,true);
 }
 // Tall grass covers plains and forest floors; it can drop wheat seeds.
 for(let lz=1;lz<15;lz++)for(let lx=1;lx<15;lx++){
  const wx=cx*16+lx,wz=cz*16+lz,info=terrainInfo(wx,wz);
  if(lakeAt(wx,wz)||riverInfo(wx,wz)||villageAt(wx,wz))continue;
  const h=H[lz*16+lx],idx=(h-MIN_Y)*256+lz*16+lx,above=idx+256;
  if(!GRASS_TYPES.has(TYPES[d[idx]])||d[above])continue;
  const chance=info.mountain>.45?.02:info.forest>.55?.42:info.valley>.35?.3:.17;
  if(hash2(wx,wz,23)<chance)d[above]=ID.tall_grass;
 }
 // Flowers grow in same-coloured patches on open grass.
 for(let lz=1;lz<15;lz++)for(let lx=1;lx<15;lx++){
  const wx=cx*16+lx,wz=cz*16+lz,info=terrainInfo(wx,wz);
  if(lakeAt(wx,wz)||riverInfo(wx,wz)||villageAt(wx,wz))continue;
  const h=H[lz*16+lx],idx=(h-MIN_Y)*256+lz*16+lx,above=idx+256;
  if(!GRASS_TYPES.has(TYPES[d[idx]])||d[above]||hash2(wx,wz,41)>=(info.biome==='fairy_forest'?.035:info.mountain>.45?.002:info.biome==='jungle'?.014:.011))continue;
  d[above]=ID['flower_'+(info.biome==='fairy_forest'?(hash2(wx,wz,44)<.52?'pink':'purple'):DYE_NAMES[Math.floor(hash2(Math.floor(wx/7),Math.floor(wz/7),43)*DYE_NAMES.length)])];
  if((above>>8)>ch.top)ch.top=above>>8;
 }
 // Sugar cane grows on shoreline sand beside water.
 for(let lz=0;lz<16;lz++)for(let lx=0;lx<16;lx++){
  const col=lz*16+lx;if(!SD[col]||W[col])continue;
  const wx=cx*16+lx,wz=cz*16+lz,h=H[col];
  if(hash2(wx,wz,120)>=.4||d[(h-MIN_Y)*256+col]!==ID.sand||d[(h+1-MIN_Y)*256+col])continue;
  if(![[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dz])=>{const t=waterTopAt(wx+dx,wz+dz);return t!==null&&t>=h;}))continue;
  const n=1+Math.floor(hash2(wx,wz,121)*3);
  for(let i=1;i<=n;i++)set(lx,h+i,lz,ID.sugar_cane,true);
  caneKeys.add(key(wx,h+1,wz));
 }
 // Houses, paths, farm plots, and loot chests. Plans are shared per village.
 const gx=Math.floor(cx*16/VILLAGE_GRID),gz=Math.floor(cz*16/VILLAGE_GRID);
 for(let a=gx-1;a<=gx+1;a++)for(let b=gz-1;b<=gz+1;b++){
  const v=villageInfo(a,b);if(!v)continue;
  if(Math.abs(cx*16+8-v.cx)>40||Math.abs(cz*16+8-v.cz)>40)continue;
  for(const [wx,wy,wz,type,meta] of villagePlan(v)){
   const lx=wx-cx*16,lz=wz-cz*16;
   if(lx<0||lx>15||lz<0||lz>15||wy<MIN_Y||wy>=MIN_Y+HT)continue;
   set(lx,wy,lz,type?ID[type]:0);
   if(type==='chest')villageChestKeys.add(villageChestKey(wx,wy,wz));
   if(type==='wheat_crop')cropKeys.add(key(wx,wy,wz));
  }
 }
 buildFairyTreeHomesForChunk(cx,cz,set);
 const e=edits.get(ck(cx,cz));
 if(e)e.forEach((v,i)=>{d[i]=v&255;ch.meta[i]=v>>8;const yy=(i/256)|0;if(yy>ch.top)ch.top=yy;
  const t=TYPES[v&255];if(t&&t.endsWith('_sapling')){const col=i%256,lx=col%16,lz=Math.floor(col/16),wx=cx*16+lx,wz=cz*16+lz;saplingKeys.add(key(wx,yy+MIN_Y,wz));}
 });
 return ch;
}

