// [geometry, material, rotationY] pieces that make up one block
function paneConnect(x,y,z){const t=getBlock(x,y,z);return t==='glass_pane'||t==='glass'||(!!t&&!!OPAQUE[ID[t]]);}
function fenceConnect(x,y,z){const t=getBlock(x,y,z);return !!FENCE_OF[t]||(!!t&&!!OPAQUE[ID[t]]);}
function wallConnect(x,y,z){return ['stone_wall','cobblestone_wall','stone_brick_wall'].includes(getBlock(x,y,z));}
function parts(type,meta,x=0,y=0,z=0){
 const f=meta&3,r=f*Math.PI/2;
 const top=!!(meta&4);
 const sh=SHP[type];
 if(type==='stone_wall'||type==='cobblestone_wall'||type==='stone_brick_wall'){
  const mt=type==='stone_wall'?'stone':type==='cobblestone_wall'?'cobblestone':'stone_bricks',p=[['stoneWallPost',mt,0]];
  if(wallConnect(x+1,y,z))p.push(['stoneWallRail',mt,0]);
  if(wallConnect(x-1,y,z))p.push(['stoneWallRail',mt,Math.PI]);
  if(wallConnect(x,y,z+1))p.push(['stoneWallRail',mt,-Math.PI/2]);
  if(wallConnect(x,y,z-1))p.push(['stoneWallRail',mt,Math.PI/2]);
  return p;
 }
 if(type==='oak_sapling'||type==='birch_sapling'||type==='spruce_sapling')return [['sapling',type,0],['sapling',type,Math.PI/2]];
 if(type==='furniture_table')return [['furnitureTop','furniture_table',0],['furnitureLegNW','planks',0],['furnitureLegNE','planks',0],['furnitureLegSW','planks',0],['furnitureLegSE','planks',0]];
 if(type==='stonecutter')return [['stonecutterBase','stonecutter',0],['stonecutterTop','stonecutterTop',0],['stonecutterBlade','stonecutterBlade',0]];
 if(type==='couch')return [['couchBase','furnitureWood',r],['couchSeat','furnitureFabric',r],['couchBack','furnitureWood',r],['couchSeatPadL','furnitureFabric',r],['couchSeatPadR','furnitureFabric',r],['couchBackPadL','furnitureAccent2',r],['couchBackPadR','furnitureAccent',r],['couchArmL','furnitureWood',r],['couchArmR','furnitureWood',r],['couchArmPadL','furnitureAccent',r],['couchArmPadR','furnitureAccent',r],['couchFootL','furnitureWood',r],['couchFootR','furnitureWood',r],['couchFootBL','furnitureWood',r],['couchFootBR','furnitureWood',r]];
 if(type==='chair')return [['chairSeat','furnitureFabric',r],['chairBack','furnitureWood',r],['chairBackPad','furnitureAccent2',r],['chairArmL','furnitureWood',r],['chairArmR','furnitureWood',r],['chairArmTopL','furnitureAccent',r],['chairArmTopR','furnitureAccent',r],['chairLegNW','furnitureWood',r],['chairLegNE','furnitureWood',r],['chairLegSW','furnitureWood',r],['chairLegSE','furnitureWood',r]];
 if(type==='shelf')return [['shelfBack','furnitureWood',r],['shelfBoardTop','furnitureWood',r],['shelfBoardMid','furnitureWood',r],['shelfBoardLow','furnitureWood',r],['shelfSideL','furnitureWood',r],['shelfSideR','furnitureWood',r],['shelfBookA','bookRed',r],['shelfBookB','bookBlue',r],['shelfBookC','bookGold',r],['shelfBookD','bookGreen',r],['shelfBookE','bookPurple',r],['shelfBookF','bookRed',r]];
 if(sh){const bm=sh[0];if(sh[1]==='slab')return [[top?'slabTop':'slab',bm,0]];if(sh[1]==='double')return [['cube',bm,0]];return [[top?'slabTop':'slab',bm,0],[top?'stairLo':'stairHi',bm,r]];}
 if(type==='sugar_cane')return [['crop2','sugar_cane',0],['crop2','sugar_cane',Math.PI/2]];
 if(DOOR_BLOCKS.has(type))return [[meta&4?'doorO':'doorC',type+(meta&4?'_o':''),r]];
 if(type==='chest')return [['chest','chest'+f,0]];
 if(type==='ladder')return [['ladder','ladder',r]];
 if(TRAP_TYPES.has(type))return [[meta&4?'doorC':(meta&8?'trapTop':'trapBot'),type,meta&4?r:0]];
 if(type==='torch')return meta&4?[['torchWallStick','torchWood',r],['torchWallFlame','flame',r]]:[['torchStick','torchWood',0],['torchFlame','flame',0]];
 if(type==='lantern')return meta&4?[['lanternBodyH','lantern',0],['lanternCapH','lanternFrame',0],['lanternChain','lanternFrame',0]]:[['lanternBody','lantern',0],['lanternCap','lanternFrame',0],['lanternRing','lanternFrame',0]];
 if(type==='glass_pane'){const p=[['panePost','glass',0]];[[1,0],[0,-1],[-1,0],[0,1]].forEach(([dx,dz],i)=>{if(paneConnect(x+dx,y,z+dz))p.push(['paneArm','glass',i*Math.PI/2]);});return p;}
 if(type.startsWith('cushion')){const k=type==='cushion'?'wool':'wool_'+type.slice(8),L=meta&4?'L':'';return [['cushionBody'+L,k,0],['cushionTop'+L,k,0]];}
 if(type==='wheat_crop'){const s=meta&3,g='crop'+s;return [[g,'wheat'+s,0],[g,'wheat'+s,Math.PI/2]];}
 if(type==='tall_grass')return [['crop2','tallGrass',0],['crop2','tallGrass',Math.PI/2]];
 if(type==='water'){const lv=meta&7;return [[lv?('water'+Math.min(lv,6)):'cube','water',0]];}
 if(type==='sign')return [['signPost','planks',r],['signBoard','sign',r]];
 if(type==='pot'){const p=[['potBody','pot',0],['potDirt','potDirt',0]];if(meta>0&&meta<=DYE_NAMES.length){const fm='flower_'+DYE_NAMES[meta-1];p.push(['potFlower',fm,0],['potFlower',fm,Math.PI/2]);}return p;}
 if(type.startsWith('flower_'))return [['flowerPlane',type,0],['flowerPlane',type,Math.PI/2]];
 if(type==='bed_foot'||type==='bed_head')return [['bed',(type==='bed_head'?'bedHead':'bedFoot')+((meta>>4)||''),r],['bedLegA','planks',r],['bedLegB','planks',r]];
 if(FENCE_OF[type]){
  const fm=FENCE_OF[type],p=[['fencePost',fm,0]];
  [[1,0],[0,-1],[-1,0],[0,1]].forEach(([dx,dz],i)=>{if(fenceConnect(x+dx,y,z+dz))p.push(['fenceRail',fm,i*Math.PI/2],['fenceRailLow',fm,i*Math.PI/2])});return p;
 }
 if(type==='stone_penis')return ['penisShaft','penisTip','penisBaseA','penisBaseB'].map(g=>[g,'cobblestone',r]);
 return [['cube',type,0]];
}
function rotBox(b,f){
 const R=(x,z)=>[[x,z],[z,-x],[-x,-z],[-z,x]][f];
 const a=R(b[0],b[2]),c=R(b[3],b[5]);
 return [Math.min(a[0],c[0]),b[1],Math.min(a[1],c[1]),Math.max(a[0],c[0]),b[4],Math.max(a[1],c[1])];
}
// collision / targeting boxes relative to block centre; null = full cube
function blockBoxes(type,meta,x=0,y=0,z=0){
 const f=meta&3;
 const top=!!(meta&4);
 const sh=SHP[type];
 if(type==='sugar_cane')return [[-.4,-.5,-.4,.4,.5,.4]];
 if(type==='oak_sapling'||type==='birch_sapling'||type==='spruce_sapling')return [];
 if(type==='stone_wall'||type==='cobblestone_wall'||type==='stone_brick_wall')return [[-.22,-.5,-.22,.22,.5,.22],[-.5,-.5,-.11,.5,.18,.11],[-.11,-.5,-.5,.11,.18,.5]];
 if(sh&&sh[1]==='slab')return [[-.5,top?0:-.5,-.5,.5,top?.5:0,.5]];
 if(sh&&sh[1]==='stairs')return [[-.5,top?0:-.5,-.5,.5,top?.5:0,.5],rotBox([-.5,top?-.5:0,-.5,.5,top?0:.5,0],f)];
 if(type==='chest')return [[-.4375,-.5,-.4375,.4375,.375,.4375]];
 if(type==='ladder')return [rotBox([-.5,-.5,.3125,.5,.5,.5],f)];
 if(TRAP_TYPES.has(type))return [meta&4?rotBox([-.5,-.5,.3125,.5,.5,.5],f):meta&8?[-.5,.3125,-.5,.5,.5,.5]:[-.5,-.5,-.5,.5,-.3125,.5]];
 if(type==='water')return [];
 if(type==='wheat_crop')return [[-.45,-.5,-.45,.45,.75,.45]];
 if(type==='tall_grass')return [[-.42,-.5,-.42,.42,.5,.42]];
 if(type==='torch')return [meta&4?rotBox([-.09,-.3,.15,.09,.3,.5],f):[-.09,-.5,-.09,.09,.22,.09]];
 if(type==='lantern')return [meta&4?[-.19,-.15,-.19,.19,.5,.19]:[-.19,-.5,-.19,.19,-.06,.19]];
 if(type==='glass_pane'){const b=[[-.0625,-.5,-.0625,.0625,.5,.0625]];
  if(paneConnect(x+1,y,z))b.push([0,-.5,-.0625,.5,.5,.0625]);if(paneConnect(x-1,y,z))b.push([-.5,-.5,-.0625,0,.5,.0625]);
  if(paneConnect(x,y,z+1))b.push([-.0625,-.5,0,.0625,.5,.5]);if(paneConnect(x,y,z-1))b.push([-.0625,-.5,-.5,.0625,.5,0]);return b;}
 if(type.startsWith('cushion'))return meta&4?[[-.37,-1,-.37,.37,-.83,.37]]:[[-.37,-.5,-.37,.37,-.33,.37]];
 if(type==='sign')return [rotBox([-.45,-.05,-.06,.45,.45,.06],f),[-.06,-.5,-.06,.06,-.05,.06]];
 if(type==='pot')return [[-.1875,-.5,-.1875,.1875,-.125,.1875]];
 if(type.startsWith('flower_'))return [[-.3,-.5,-.3,.3,.2,.3]];
 if(type==='bed_foot'||type==='bed_head')return [[-.5,-.5,-.5,.5,.05,.5]];
 if(type==='stone_penis')return [[-.16,-.5,-.16,.16,.44,.16],[-.4,-.5,-.2,.4,-.2,.2]];
 if(FENCE_OF[type]){
  const b=[[-.125,-.5,-.125,.125,1,.125]];
  if(fenceConnect(x+1,y,z))b.push([0,-.5,-.1,.5,1,.1]);
  if(fenceConnect(x-1,y,z))b.push([-.5,-.5,-.1,0,1,.1]);
  if(fenceConnect(x,y,z+1))b.push([-.1,-.5,0,.1,1,.5]);
  if(fenceConnect(x,y,z-1))b.push([-.1,-.5,-.5,.1,1,0]);
  return b;
 }
 if(DOOR_BLOCKS.has(type))return [rotBox(meta&4?[-.5,-.5,-.5,-.3125,.5,.5]:[-.5,-.5,.3125,.5,.5,.5],f)];
 return null;
}
function clearMeshes(ch){ch.meshes.forEach(m=>{scene.remove(m);m.dispose();});ch.meshes=[];}
function buildChunk(ch){
 clearMeshes(ch);ch.torches=[];
 const d=ch.data,lists={};
 for(let y=0;y<=ch.top;y++)for(let lz=0;lz<16;lz++)for(let lx=0;lx<16;lx++){
  const i=y*256+lz*16+lx,id=d[i];if(!id)continue;
  const wx=ch.cx*16+lx,wy=y+MIN_Y,wz=ch.cz*16+lz;
  if(id===ID.torch||id===ID.lantern)ch.torches.push(new THREE.Vector3(wx,wy+.2,wz));
  if(id===ID.water&&getId(wx,wy+1,wz)===ID.water)continue;
  const ex=!OPAQUE[id]||(lx>0?!OPAQUE[d[i-1]]:!OPAQUE[getId(wx-1,wy,wz)])||(lx<15?!OPAQUE[d[i+1]]:!OPAQUE[getId(wx+1,wy,wz)])||
   (lz>0?!OPAQUE[d[i-16]]:!OPAQUE[getId(wx,wy,wz-1)])||(lz<15?!OPAQUE[d[i+16]]:!OPAQUE[getId(wx,wy,wz+1)])||
   (y<HT-1?!OPAQUE[d[i+256]]:true)||(y>0?!OPAQUE[d[i-256]]:false);
  if(!ex)continue;
  for(const [g,m,r] of parts(TYPES[id],ch.meta[i],wx,wy,wz))(lists[g+'|'+m]||(lists[g+'|'+m]=[])).push(wx,wy,wz,r);
 }
 for(const k in lists){
  const [g,m]=k.split('|'),L=lists[k],n=L.length/4;
  const mesh=new THREE.InstancedMesh(GEO[g],materials[m],n);
  for(let j=0;j<n;j++){
   dummy.position.set(L[j*4],L[j*4+1],L[j*4+2]);dummy.rotation.y=L[j*4+3];dummy.updateMatrix();
   mesh.setMatrixAt(j,dummy.matrix);
  }
  mesh.instanceMatrix.needsUpdate=true;mesh.computeBoundingSphere();
  scene.add(mesh);ch.meshes.push(mesh);
 }
}
function rebuild(cx,cz){const c=chunks.get(ck(cx,cz));if(c)buildChunk(c);}

function setBlockWorldLocal(x,y,z,type,meta=0,defer=false){
 const yy=y-MIN_Y;if(yy<0||yy>=HT)return false;
 const cx=Math.floor(x/CS),cz=Math.floor(z/CS),ch=chunks.get(ck(cx,cz));if(!ch)return false;
 if(type&&!ID[type])return false;
 const lx=x-cx*CS,lz=z-cz*CS,idx=yy*256+lz*CS+lx,id=type?ID[type]:0;
 const oldType=TYPES[ch.data[idx]];
 if(oldType&&oldType.endsWith('_sapling')&&oldType!==type)saplingKeys.delete(key(x,y,z));
 if(type&&type.endsWith('_sapling'))saplingKeys.add(key(x,y,z));
 ch.data[idx]=id;ch.meta[idx]=meta;if(yy>ch.top)ch.top=yy;
 let e=edits.get(ck(cx,cz));if(!e)edits.set(ck(cx,cz),e=new Map());
 e.set(idx,id|(meta<<8));
 if(defer){
  waterDirty.add(ck(cx,cz));
  if(lx===0)waterDirty.add(ck(cx-1,cz));
  if(lx===CS-1)waterDirty.add(ck(cx+1,cz));
  if(lz===0)waterDirty.add(ck(cx,cz-1));
  if(lz===CS-1)waterDirty.add(ck(cx,cz+1));
 }else{
  buildChunk(ch);
  if(lx===0)rebuild(cx-1,cz);
  if(lx===CS-1)rebuild(cx+1,cz);
  if(lz===0)rebuild(cx,cz-1);
  if(lz===CS-1)rebuild(cx,cz+1);
 }
 lightTimer=0;
 if(waterSimActive)queueWaterAround(x,y,z);
 return true;
}
function queueWaterAt(x,y,z){
 if(waterQueue.length>5000)return;
 const k=key(x,y,z);if(waterPending.has(k)||!canPlaceAt(x,y,z)||getBlock(x,y,z)!=='water')return;
 waterPending.add(k);waterQueue.push([x,y,z]);
}
function queueWaterAround(x,y,z){
 queueWaterAt(x,y,z);
 queueWaterAt(x+1,y,z);queueWaterAt(x-1,y,z);queueWaterAt(x,y+1,z);queueWaterAt(x,y-1,z);queueWaterAt(x,y,z+1);queueWaterAt(x,y,z-1);
}
function updateWaterCell(x,y,z){
 const level=getMeta(x,y,z)&7;
 if(level>0){
  let supported=getBlock(x,y+1,z)==='water';
  const dirs=[[1,0],[-1,0],[0,1],[0,-1]];
  for(const [dx,dz] of dirs){const t=getBlock(x+dx,y,z+dz);if(t==='water'&&(getMeta(x+dx,y,z+dz)&7)<level){supported=true;break;}}
  if(!supported){setBlockWorld(x,y,z,null,0,true);return;}
  // Flowing water between two sources (over a solid floor or source) refills, so scooped rivers and ponds recover.
  let sources=0;
  for(const [dx,dz] of dirs)if(getBlock(x+dx,y,z+dz)==='water'&&!(getMeta(x+dx,y,z+dz)&7))sources++;
  const bt=getBlock(x,y-1,z);
  if(sources>=2&&((bt==='water'&&!(getMeta(x,y-1,z)&7))||(bt&&OPAQUE[ID[bt]]))){setBlockWorld(x,y,z,'water',0,true);return;}
 }
 const belowY=y-1,below=getBlock(x,belowY,z);
 if(belowY>=MIN_Y&&(below===undefined||below==='tall_grass'||below==='wheat_crop'||below==='torch')){
  setBlockWorld(x,belowY,z,'water',1,true);return;
 }
 if(below==='water')return;
 const next=level+1;if(next>6)return;
 for(const [dx,dz] of [[1,0],[-1,0],[0,1],[0,-1]]){
  const nx=x+dx,nz=z+dz,t=getBlock(nx,y,nz);
  if(t===undefined||t==='tall_grass'||t==='wheat_crop'||t==='torch')setBlockWorld(nx,y,nz,'water',next,true);
 }
}
function tickWater(){
 let budget=48;
 while(budget-->0&&waterQueue.length){
  const [x,y,z]=waterQueue.shift();waterPending.delete(key(x,y,z));
  if(canPlaceAt(x,y,z)&&getBlock(x,y,z)==='water')updateWaterCell(x,y,z);
 }
 for(const k of waterDirty){const ch=chunks.get(k);if(ch)buildChunk(ch);}
 waterDirty.clear();
}
// Every block change goes through here. Water simulation (defer=true) runs on each device, so it isn't sent.
function setBlockWorld(x,y,z,type,meta=0,defer=false){
 const ok=setBlockWorldLocal(x,y,z,type,meta,defer);
 if(ok&&!defer&&!mpApplying&&mp&&mp.joined)mpSend({t:'block',x,y,z,type:type||null,meta:meta||0});
 return ok;
}
function addBlock(x,y,z,type='grass',meta=0){return (!getId(x,y,z)||getBlock(x,y,z)==='water')&&setBlockWorld(x,y,z,type,meta);}
function removeBlock(x,y,z){setBlockWorld(x,y,z,null);}

function updateChunks(sync){
 // Bootstrap only nearby terrain; stream the rest to avoid a long GPU stall.
 const pcx=Math.floor(Math.round(player.x)/CS),pcz=Math.floor(Math.round(player.z)/CS);
 const need=[];
 for(let dx=-RADIUS;dx<=RADIUS;dx++)for(let dz=-RADIUS;dz<=RADIUS;dz++){
  if(dx*dx+dz*dz>RADIUS*RADIUS+1)continue;
  if(!chunks.has(ck(pcx+dx,pcz+dz)))need.push([dx*dx+dz*dz,pcx+dx,pcz+dz]);
 }
 need.sort((a,b)=>a[0]-b[0]);
 const n=sync?Math.min(5,need.length):Math.min(1,need.length);
 for(let i=0;i<n;i++){
  const ch=genChunk(need[i][1],need[i][2]);
  chunks.set(ck(ch.cx,ch.cz),ch);buildChunk(ch);
 }
 for(const [k,ch] of chunks){
  const dx=ch.cx-pcx,dz=ch.cz-pcz;
  if(dx*dx+dz*dz>(RADIUS+1)*(RADIUS+1)+2){clearMeshes(ch);chunks.delete(k);}
 }
}

/* ================= PLAYER ================= */

const player={x:0,z:5,feet:heightAt(0,5)+2,vy:0,grounded:false};
const survival={health:20,hunger:20,stamina:100,xp:0,xpLevel:0,dead:false,exhausted:false,sprinting:false,starve:0,regen:0,fallPeak:player.feet,attackCooldown:0,eatCooldown:0};
const worldSpawn={x:0,z:5};
let bedSpawn=null,sleepTimer=0,dayTime=.2,dayNumber=1;
const DAY_SECONDS=600; // Ten-minute days, including a night you can sleep through.
const PLAYER_WIDTH=.6,PLAYER_HEIGHT=1.8,EYE_HEIGHT=1.62;
let yaw=0,pitch=0;

camera.position.set(player.x,player.feet+EYE_HEIGHT,player.z);

function overlaps(px,feet,pz,x,y,z){
 return px+PLAYER_WIDTH/2>x-.5&&px-PLAYER_WIDTH/2<x+.5&&
 pz+PLAYER_WIDTH/2>z-.5&&pz-PLAYER_WIDTH/2<z+.5&&
 feet+PLAYER_HEIGHT>y-.5&&feet<y+.5;
}

function hitBoxes(px,feet,pz,x,y,z,bx){
 const hw=PLAYER_WIDTH/2;
 return (bx||[[-.5,-.5,-.5,.5,.5,.5]]).some(b=>px+hw>x+b[0]&&px-hw<x+b[3]&&pz+hw>z+b[2]&&pz-hw<z+b[5]&&feet+PLAYER_HEIGHT>y+b[1]&&feet<y+b[4]);
}
function blockHit(px,feet,pz,x,y,z){
 const t=getBlock(x,y,z);
 return !!t&&t!=='water'&&t!=='torch'&&t!=='wheat_crop'&&t!=='tall_grass'&&t!=='sugar_cane'&&t!=='sign'&&!t.startsWith('flower_')&&!t.startsWith('cushion')&&hitBoxes(px,feet,pz,x,y,z,blockBoxes(t,getMeta(x,y,z),x,y,z));
}
function collides(px,feet,pz){
 const minX=Math.floor(px-PLAYER_WIDTH/2-.5);
 const maxX=Math.floor(px+PLAYER_WIDTH/2+.5);
 const minZ=Math.floor(pz-PLAYER_WIDTH/2-.5);
 const maxZ=Math.floor(pz+PLAYER_WIDTH/2+.5);
 const minY=Math.floor(feet-1.5);
 const maxY=Math.floor(feet+PLAYER_HEIGHT+.5);

 for(let x=minX;x<=maxX;x++){
  for(let y=minY;y<=maxY;y++){
   for(let z=minZ;z<=maxZ;z++){
    if(blockHit(px,feet,pz,x,y,z))return true;
   }
  }
 }
 return false;
}

function moveHorizontal(dx,dz){
 const steps=Math.max(1,Math.ceil(Math.max(Math.abs(dx),Math.abs(dz))/.08));
 const sx=dx/steps,sz=dz/steps;

 for(let i=0;i<steps;i++){
  const step=(ax,az)=>{
   if(!collides(player.x+ax,player.feet,player.z+az)){player.x+=ax;player.z+=az;}
   else if(player.grounded&&!collides(player.x+ax,player.feet+.55,player.z+az)){player.feet+=.55;player.x+=ax;player.z+=az;}
  };
  step(sx,0);step(0,sz);
 }
}

function moveVertical(amount){
 const steps=Math.max(1,Math.ceil(Math.abs(amount)/.08));
 const step=amount/steps;
 player.grounded=false;

 for(let i=0;i<steps;i++){
  if(!collides(player.x,player.feet+step,player.z)){
   player.feet+=step;
  }else{
   if(step<0){
    player.grounded=true;
    const fall=survival.fallPeak-player.feet;
    if(!isInWater()&&fall>3)damagePlayer(Math.floor(fall-3),'a hard landing',true);
    survival.fallPeak=player.feet;
   }
   player.vy=0;
   break;
  }
 }
}

/* ================= INPUT ================= */

const keys={};
const touchMode=('ontouchstart' in window)||(navigator.maxTouchPoints||0)>0||(window.matchMedia&&window.matchMedia('(pointer: coarse)').matches);
if(touchMode)document.body.classList.add('touch-mode');
let pointerLocked=false;
let touchClosePanel=null;
let inventoryOpen=false;
let tableOpen=false;
let stonecutterOpen=false;
let tableStation='crafting';
let menuOpen=true,started=false,inGame=false,currentWorld=null;
let saveTimer=0,lastSaveTime=0;
function updateStartOverlay(){
 start.style.display=(started&&!menuOpen&&!survival.dead&&!touchMode&&!pointerLocked&&!inventoryOpen&&!tableOpen&&!furnaceOpen&&!chestOpen&&!stonecutterOpen&&!signOpen)?'flex':'none';
 if(touchClosePanel)touchClosePanel.style.display=touchMode&&(inventoryOpen||tableOpen||furnaceOpen||chestOpen||stonecutterOpen||signOpen)?'block':'none';
}

const start=document.getElementById('start');
const inventory=document.getElementById('inventory');
const tableInventory=document.getElementById('tableInventory');

function showNotice(text){
 const el=document.getElementById('notice');el.textContent=text;el.style.display='block';
 clearTimeout(showNotice.timer);showNotice.timer=setTimeout(()=>el.style.display='none',2600);
}
function pauseInput(){
 for(const k in keys)keys[k]=false;
 mining=false;mineProgress=0;
 if(touchMode){if(typeof clearMoveStick==='function')clearMoveStick();lookPointer=null;touchMine?.classList.remove('pressed');touchJump?.classList.remove('pressed');touchDown?.classList.remove('pressed');}
}
function toggleInventory(){
 if(survival.dead||sleepTimer>0)return;
 if(inventoryOpen){
  inventoryOpen=false;
  returnItems();
  inventory.style.display='none';
  updateStartOverlay();
 }else{
  pauseInput();
  inventoryOpen=true;
  tableOpen=false;
  inventory.style.display='block';
  tableInventory.style.display='none';
  if(pointerLocked)document.exitPointerLock();
  start.style.display='none';
  updateStartOverlay();
  renderInventory();
 }
}

start.addEventListener('click',()=>{
 if(survival.dead||menuOpen||!started)return;
 if(touchMode){updateStartOverlay();return;}
 const request=renderer.domElement.requestPointerLock();
 if(request?.catch)request.catch(()=>showNotice('Click the game again to capture the mouse.'));
});

// Touch input: left thumb joystick, right thumb camera look, and explicit action buttons.
const movePad=document.getElementById('movePad'),moveNub=document.getElementById('moveNub');
const lookPad=document.getElementById('touchLookPad');
const touchBag=document.getElementById('touchBag'),touchJump=document.getElementById('touchJump');
const touchMine=document.getElementById('touchMine'),touchPlace=document.getElementById('touchPlace'),touchDown=document.getElementById('touchDown');
const touchDrop=document.getElementById('touchDrop'),touchMenu=document.getElementById('touchMenu');
touchClosePanel=document.getElementById('touchClosePanel');
touchClosePanel.addEventListener('click',()=>{if(mapOpen)toggleMap();else if(signOpen)closeSign(false);else if(chestOpen)closeChest();else if(furnaceOpen)closeFurnace();else if(stonecutterOpen)closeStonecutter();else if(tableOpen)closeTable();else if(inventoryOpen)toggleInventory();});
let movePointer=null,lookPointer=null,lastLookX=0,lastLookY=0;
function clearMoveStick(){movePointer=null;for(const k of ['KeyW','KeyA','KeyS','KeyD'])keys[k]=false;moveNub.style.transform='translate(0px,0px)';}
function setMoveFromPoint(e){
 const r=movePad.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;
 let dx=e.clientX-cx,dy=e.clientY-cy;const max=42,len=Math.hypot(dx,dy);
 if(len>max){dx=dx/len*max;dy=dy/len*max;}
 moveNub.style.transform=`translate(${dx}px,${dy}px)`;
 keys.KeyA=dx<-11;keys.KeyD=dx>11;keys.KeyW=dy<-11;keys.KeyS=dy>11;
}
movePad.addEventListener('pointerdown',e=>{if(!touchMode||menuOpen||!started)return;e.preventDefault();movePointer=e.pointerId;movePad.setPointerCapture(e.pointerId);setMoveFromPoint(e);});
movePad.addEventListener('pointermove',e=>{if(e.pointerId===movePointer){e.preventDefault();setMoveFromPoint(e);}});
for(const ev of ['pointerup','pointercancel','lostpointercapture'])movePad.addEventListener(ev,e=>{if(e.pointerId===movePointer)clearMoveStick();});
lookPad.addEventListener('pointerdown',e=>{if(!touchMode||menuOpen||!started||inventoryOpen||tableOpen||furnaceOpen||chestOpen||stonecutterOpen||signOpen)return;e.preventDefault();lookPointer=e.pointerId;lastLookX=e.clientX;lastLookY=e.clientY;lookPad.setPointerCapture(e.pointerId);});
lookPad.addEventListener('pointermove',e=>{if(e.pointerId!==lookPointer)return;e.preventDefault();const dx=e.clientX-lastLookX,dy=e.clientY-lastLookY;lastLookX=e.clientX;lastLookY=e.clientY;yaw-=dx*.006;pitch-=dy*.006;pitch=Math.max(-Math.PI/2+.01,Math.min(Math.PI/2-.01,pitch));});
for(const ev of ['pointerup','pointercancel','lostpointercapture'])lookPad.addEventListener(ev,e=>{if(e.pointerId===lookPointer)lookPointer=null;});
function virtualKey(code,down){
 const key=code==='Space'?' ':code==='ShiftLeft'?'Shift':code;
 document.dispatchEvent(new KeyboardEvent(down?'keydown':'keyup',{code,key,bubbles:true,cancelable:true}));
}
function bindHoldTouchButton(el,code){
 el.addEventListener('pointerdown',e=>{if(!touchMode)return;e.preventDefault();e.stopPropagation();el.classList.add('pressed');el.setPointerCapture(e.pointerId);virtualKey(code,true);});
 const release=e=>{if(!touchMode)return;e.preventDefault();el.classList.remove('pressed');virtualKey(code,false);};
 el.addEventListener('pointerup',release);el.addEventListener('pointercancel',release);el.addEventListener('lostpointercapture',release);
}
bindHoldTouchButton(touchJump,'Space');
bindHoldTouchButton(touchDown,'ShiftLeft');
touchBag.addEventListener('click',e=>{e.preventDefault();if(!touchMode||menuOpen)return;if(signOpen)closeSign(false);else if(chestOpen)closeChest();else if(furnaceOpen)closeFurnace();else if(stonecutterOpen)closeStonecutter();else if(tableOpen)closeTable();else toggleInventory();});
touchDrop.addEventListener('click',e=>{e.preventDefault();if(touchMode&&!menuOpen&&started&&!inventoryOpen)dropSelectedItem();});
touchMenu.addEventListener('click',e=>{e.preventDefault();if(touchMode&&!menuOpen&&inGame)openMenu(true);});
touchMine.addEventListener('pointerdown',e=>{if(!touchMode||menuOpen||!started||inventoryOpen||tableOpen||furnaceOpen||chestOpen||stonecutterOpen||signOpen||survival.dead)return;e.preventDefault();e.stopPropagation();touchMine.classList.add('pressed');touchMine.setPointerCapture(e.pointerId);if(attackMob())return;mining=true;mineProgress=0;});
const endTouchMine=e=>{if(!touchMode)return;e.preventDefault();touchMine.classList.remove('pressed');mining=false;mineProgress=0;};
touchMine.addEventListener('pointerup',endTouchMine);touchMine.addEventListener('pointercancel',endTouchMine);touchMine.addEventListener('lostpointercapture',endTouchMine);
touchPlace.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();if(!touchMode||menuOpen||!started||inventoryOpen||tableOpen||furnaceOpen||chestOpen||stonecutterOpen||signOpen||survival.dead)return;const vt=villagerTarget();if(vt){openTrade(vt);return;}placeOrUseBlock();});


document.addEventListener('pointerlockchange',()=>{
 pointerLocked=document.pointerLockElement===renderer.domElement;
 if(!pointerLocked)pauseInput();
 updateStartOverlay();
});

document.addEventListener('mousemove',e=>{
 if(touchMode||!pointerLocked||menuOpen||inventoryOpen||tableOpen||furnaceOpen||chestOpen||stonecutterOpen||signOpen)return;
 yaw-=e.movementX*.002;
 pitch-=e.movementY*.002;
 pitch=Math.max(-Math.PI/2+.01,Math.min(Math.PI/2-.01,pitch));
});

document.addEventListener('keydown',e=>{
 if(signOpen){if(mapOpen){if(e.code==='Escape'||e.code==='KeyM'){e.preventDefault();toggleMap();}return;}if(e.code==='Escape'){e.preventDefault();closeSign();}return;}
 if(menuOpen){if(e.code==='Escape'&&inGame)resumeGame();return;}
 if(!started||survival.dead||sleepTimer>0)return;
 keys[e.code]=true;
 if(e.code==='KeyY'&&!e.repeat)tryDye();
 if(e.code==='KeyQ'&&!e.repeat){e.preventDefault();dropSelectedItem();}
 if(e.code==='Space'&&!e.repeat&&gameMode==='creative'){const now=performance.now();if(now-lastCreativeSpace<320){creativeFlying=!creativeFlying;player.vy=0;survival.fallPeak=player.feet;showNotice(creativeFlying?'Creative flight enabled — Space up, Shift down.':'Creative flight disabled.');}lastCreativeSpace=now;}
 if(e.code==='KeyM'&&!e.repeat){e.preventDefault();toggleMap();return;}
 if(e.code==='F5'){e.preventDefault();viewMode=(viewMode+1)%3;showNotice(['First person','Third person (behind)','Third person (front)'][viewMode]);}

 if((e.code==='KeyE'||e.key?.toLowerCase()==='e')&&!e.repeat){
  e.preventDefault();e.stopPropagation();
  if(chestOpen)closeChest();else if(furnaceOpen)closeFurnace();else if(stonecutterOpen)closeStonecutter();else if(tableOpen)closeTable();
  else toggleInventory();
 }

 if(e.code==='Escape'){
  if(chestOpen)closeChest();else if(furnaceOpen)closeFurnace();else if(stonecutterOpen)closeStonecutter();else if(tableOpen)closeTable();
  else if(inventoryOpen)toggleInventory();
  else if(inGame)openMenu(true);
 }

 if(e.code.startsWith('Digit')){
  const n=Number(e.code.slice(5));
  if(n>=1&&n<=9){selected=n-1;updateHotbar();}
 }

 if(e.code==='Space')e.preventDefault();
});

document.addEventListener('keyup',e=>keys[e.code]=false);
window.addEventListener('blur',pauseInput);

