function drawCube(g,F,hf,dy,clip){
 g.save();
 if(clip){g.beginPath();g.rect(0,0,16,32);g.clip();}
 const s=(1-hf)*14+dy,k=14/16,h=7/16;
 g.fillStyle='#333';g.beginPath();
 [[16,2+s],[30,9+s],[30,23+dy],[16,30+dy],[2,23+dy],[2,9+s]].forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));
 g.fill();
 const face=(tex,m,shade)=>{
  g.save();g.setTransform(...m);g.drawImage(tex.image,0,0);
  if(shade){g.fillStyle=`rgba(0,0,0,${shade})`;g.fillRect(0,0,16,16);}
  g.restore();
 };
 face(F[1],[k,h,0,k*hf,2,9+s],.2);
 face(F[2]||F[1],[k,-h,0,k*hf,16,16+s],.4);
 face(F[0],[k,h,-k,h,16,2+s],0);
 g.restore();
}
// Procedural 16x16 tool sprites: shaped head mask + diagonal handle, then auto highlight / shadow / outline.
function toolGrid(kind){
 const N=16,head=Array.from({length:N},()=>Array(N).fill(0)),handle=Array.from({length:N},()=>Array(N).fill(0));
 const hx=(a,b)=>{for(let x=a;x<=b;x++){const y=14-x;if(y>=0&&y<N&&x>=0&&x<N)handle[y][x]=1;}};
 const row=(y,a,b)=>{for(let x=a;x<=b;x++)if(x>=0&&x<N&&y>=0&&y<N)head[y][x]=1;};
 if(kind==='stick')hx(2,13);
 else if(kind==='pickaxe'){
  hx(1,9);
  for(let y=0;y<N;y++)for(let x=0;x<N;x++){const dx=x+.5-5.5,dy=y+.5-9.5,d=Math.hypot(dx,dy),a=Math.atan2(dy,dx);
   if(Math.abs(a+Math.PI/4)<=1.15&&d>=5.4&&d<=7.4)head[y][x]=1;}
 }else if(kind==='axe'){
  hx(1,11);row(1,7,10);row(2,6,11);row(3,5,12);row(4,5,11);row(5,6,9);
 }else if(kind==='shovel'){
  hx(1,11);row(0,12,14);row(1,11,15);row(2,11,15);row(3,12,14);
 }else if(kind==='hoe'){
  hx(1,12);row(1,6,12);row(2,6,9);row(3,6,7);
 }else if(kind==='sword'){
  hx(1,4);
  for(let x=6;x<=14;x++){const y=14-x;if(y>=0)head[y][x]=1;if(y+1<N&&x<=13)head[y+1][x]=1;}
  head[0][14]=1;
  for(let k=-2;k<=2;k++){const x=5+k,y=9+k;head[y][x]=2;if(k)head[y][x+1]=2;}
 }
 return {head,handle,N};
}
function drawToolSprite(g,kind,P,shade){
 const {head,handle,N}=toolGrid(kind),px=(x,y,c)=>{g.fillStyle=c;g.fillRect(x*2,y*2,2,2);};
 const main=P?P[0]:'#8b5e2f',dark=P?P[1]:'#5e3d1b',light=shade(main,1.3),outline=shade(dark,.35);
 const at=(m,x,y)=>x>=0&&y>=0&&x<N&&y<N&&m[y][x];
 // handle first (so the head overlaps it)
 let i=0;for(let y=N-1;y>=0;y--)for(let x=0;x<N;x++)if(handle[y][x]){px(x,y,(i++)%2?'#7a5128':'#9a6a35');}
 const filled=(x,y)=>at(head,x,y)||at(handle,x,y);
 for(let y=0;y<N;y++)for(let x=0;x<N;x++){
  const v=head[y][x];
  if(v){
   const up=!at(head,x,y-1),left=!at(head,x-1,y),down=!at(head,x,y+1),right=!at(head,x+1,y);
   let c=main;if(v===2)c=shade('#5a5a5a',1);
   if(v===2)c=(up||left)?'#8a8a8a':'#5a5a5a';
   else if(up||left)c=light;else if(down||right)c=dark;
   px(x,y,c);
  }
 }
 for(let y=0;y<N;y++)for(let x=0;x<N;x++){
  if(filled(x,y))continue;
  if(at(head,x+1,y)||at(head,x-1,y)||at(head,x,y+1)||at(head,x,y-1))px(x,y,outline);
 }
}

