function handleSlotClick(arr,index,e){
 const item=arr[index];
 if(e?.shiftKey&&!cursorItem&&item&&(ITEMS[item.type]?.armor!==undefined||ITEMS[item.type]?.back)){
  if(ITEMS[item.type]?.back){arr[index]=backSlot;backSlot=item;}
  else{const slot=ITEMS[item.type].armor;arr[index]=armorSlots[slot];armorSlots[slot]=item;}
  renderInventory();if(tableOpen)renderTable();if(chestOpen)renderChest();if(furnaceOpen)renderFurnace();updateHotbar();
  return;
 }

 if(!cursorItem){
  if(item){cursorItem=item;arr[index]=null;}
 }else if(!item){
  arr[index]=cursorItem;cursorItem=null;
 }else if(item.type===cursorItem.type&&maxStack(item.type)>1&&item.count<maxStack(item.type)){
  const amount=Math.min(cursorItem.count,maxStack(item.type)-item.count);
  item.count+=amount;cursorItem.count-=amount;
  if(cursorItem.count<=0)cursorItem=null;
 }else{
  arr[index]=cursorItem;cursorItem=item;
 }

 renderInventory();
 if(tableOpen)renderTable();
 if(furnaceOpen)renderFurnace();
 if(chestOpen)renderChest();
 if(stonecutterOpen)renderStonecutter();
}

