// Right-click slots: take half a stack, or place ONE item from the cursor.
function handleRightSlot(arr,index){
 const item=arr[index];
 if(cursorItem){
  if(!item){if(cursorItem.count===1){arr[index]=cursorItem;cursorItem=null}else{arr[index]=createItem(cursorItem.type,1);cursorItem.count--}}
  else if(item.type===cursorItem.type&&maxStack(item.type)>1&&item.count<maxStack(item.type)){item.count++;cursorItem.count--;if(cursorItem.count<=0)cursorItem=null}
 }else if(item){
  if(item.count===1){cursorItem=item;arr[index]=null;}
  else{const amount=Math.ceil(item.count/2);cursorItem=createItem(item.type,amount);item.count-=amount;}
 }
 renderInventory();if(tableOpen)renderTable();if(furnaceOpen)renderFurnace();if(chestOpen)renderChest();if(stonecutterOpen)renderStonecutter();updateHotbar();updateCursorItem();
}
function attachRightClick(container,arr,selector,dataKey){
 container.addEventListener('contextmenu',e=>{
  const el=e.target.closest(selector);if(!el)return;
  e.preventDefault();
  handleRightSlot(arr,Number(el.dataset[dataKey]));
 });
}
