// Works for both the 2x2 and 3x3 grids. Recipes are placed anywhere in the grid.
const isPlank=t=>t==='planks'||t.endsWith('_planks')||t.startsWith('planks_');
function matchRecipe(grid,station='crafting'){
 const n=Math.round(Math.sqrt(grid.length));
 const filled=[];grid.forEach((it,i)=>{if(it)filled.push(i)});
 if(station!=='furniture'&&filled.length===1&&grid[filled[0]].type==='log')return{r:['planks',4],cells:filled};
 if(station!=='furniture'&&filled.length===1&&grid[filled[0]].type==='hay_bale')return{r:['wheat',9],cells:filled};
 if(station!=='furniture'&&filled.length===4&&filled.map(i=>grid[i].type).sort().join()==='leather,paper,paper,paper')return{r:['book',1],cells:filled};
 if(station!=='furniture'&&filled.length===1&&grid[filled[0]].type.startsWith('flower_'))return{r:['dye_'+grid[filled[0]].type.slice(7),1],cells:filled};
 if(station!=='furniture'&&filled.length===2){
  const a=grid[filled[0]].type,b=grid[filled[1]].type;
  const isW=t=>t==='wool'||DYE_NAMES.some(c=>t==='wool_'+c),w=[a,b].find(isW),dd=[a,b].find(t=>t.startsWith('dye_'));
  if(w&&dd)return{r:['wool_'+dd.slice(4),1],cells:filled};
 }
 for(const rec of RECIPES){
  if(rec.station&&rec.station!==station)continue;
  if(!rec.station&&station==='furniture')continue;
  const rows=rec.p.length,cols=Math.max(...rec.p.map(row=>row.length));
  for(let oy=0;oy<=n-rows;oy++)for(let ox=0;ox<=n-cols;ox++){
   let ok=true;const cells=[];
   for(let y=0;y<n&&ok;y++)for(let x=0;x<n;x++){
    const exp=(y>=oy&&y<oy+rows&&x>=ox&&x<ox+cols)?rec.p[y-oy][x-ox]:0;
    const it=grid[y*n+x];
    if(exp){if(!it||!(exp==='any_planks'?isPlank(it.type):it.type===exp)){ok=false;break}cells.push(y*n+x)}
    else if(it){ok=false;break}
   }
   if(ok)return{r:rec.r,cells};
  }
 }
 return null;
}
function renderRecipeBook(){
 const featured=['torch','bed','fence','bread','wooden_sword','wooden_shovel','wooden_hoe','stone_penis','furnace','slab','stairs','door','chest','iron_sword','iron_chestplate','diamond_sword','diamond_pickaxe','diamond_chestplate','rhinestone_pickaxe','rhinestone_chestplate','sign','ladder','trapdoor','bucket','paper','book','bookshelf','hay_bale','leather_chestplate','stone_slab','stone_stairs','wool_slab','wool_stairs','bed_blue','stonecutter','furniture_table','birch_planks','spruce_planks','jungle_planks','pink_planks','purple_planks','couch','chair','shelf','fairy_wings','bow','arrow','bricks','pot','clay','lantern','glass_pane','cushion',...WOOD_LIST.flatMap(k=>[k+'_slab',k+'_stairs',k+'_door',k+'_trapdoor',k+'_fence'])];
 document.querySelectorAll('.recipeList').forEach(list=>{
  list.innerHTML='';
  featured.forEach(type=>{
   const rec=RECIPES.find(r=>r.r[0]===type);if(!rec)return;const card=document.createElement('div');card.className='recipeCard';
   const name=document.createElement('strong');name.textContent=itemName(type);card.appendChild(name);
   const line=document.createElement('div');line.className='recipeLine';
   const pattern=document.createElement('div');pattern.className='recipePattern';
   for(let y=0;y<3;y++)for(let x=0;x<3;x++){
    const cell=document.createElement('span');cell.className='recipeCell';const ingredient=rec.p[y]?.[x];
    if(ingredient){const img=document.createElement('img'),any=ingredient==='any_planks';img.src=iconFor(any?'planks':ingredient);img.alt=any?'Any Planks':itemName(ingredient);cell.title=img.alt;cell.appendChild(img);}
    pattern.appendChild(cell);
   }
   const arrow=document.createElement('span');arrow.textContent='→';
   const out=document.createElement('span');out.className='recipeOutput';
   const icon=document.createElement('img');icon.src=iconFor(type);icon.alt=itemName(type);
   const count=document.createElement('span');count.textContent='×'+rec.r[1];out.append(icon,count);
   line.append(pattern,arrow,out);card.appendChild(line);list.appendChild(card);
  });
 });
}
function craftPreview(grid,station='crafting'){const m=matchRecipe(grid,station);return m?createItem(m.r[0],m.r[1]):null;}
function doCraft(grid,station='crafting'){
 const m=matchRecipe(grid,station);
 if(!m)return;
 if(!canFit(m.r[0],m.r[1])){showNotice('Make room in your inventory before crafting.');return;}
 m.cells.forEach(i=>{if(--grid[i].count<=0)grid[i]=null});
 addItem(m.r[0],m.r[1]);
}
