/* ================= FURNACE ================= */

const SMELT={clay_ball:'brick',sand:'glass',iron_ore:'iron_ingot',cobblestone:'stone',raw_beef:'cooked_beef',raw_pork:'cooked_pork',raw_mutton:'cooked_mutton'};
const FUEL={coal:80,log:15,birch_log:15,spruce_log:15,stripped_log:15,stripped_birch_log:15,stripped_spruce_log:15,planks:15,birch_planks:15,spruce_planks:15,stick:5};
for(const k of ['jungle','pink','purple'])Object.assign(FUEL,{[k+'_log']:15,[k+'_planks']:15});
for(const k of ['oak',...WOOD_LIST]){const P=k==='oak'?'':k+'_';Object.assign(FUEL,{[P+'slab']:8,[P+'stairs']:15,[P+'fence']:15,[P+'trapdoor']:15});}
const furnaces=new Map();
let furnaceOpen=false,curFurnace=null;
const furnacePanel=document.getElementById('furnacePanel');
const fIn=document.getElementById('furnIn'),fFuel=document.getElementById('furnFuel'),fOut=document.getElementById('furnOut');
const fBurn=document.getElementById('furnBurn'),fCook=document.getElementById('furnCook');
const furnInv=document.getElementById('furnInv'),furnHotbar=document.getElementById('furnHotbar');

function getFurnace(k){
 let f=furnaces.get(k);
 if(!f){f={slots:[null,null,null],burn:0,burnMax:0,cook:0};furnaces.set(k,f);}
 return f;
}
function dropFurnace(k,x=player.x,y=player.feet,z=player.z){
 const f=furnaces.get(k);if(!f)return;
 f.slots.forEach(it=>{if(it)spawnWorldDrop(it.type,it.count,x+(Math.random()-.5)*.35,y+.35,z+(Math.random()-.5)*.35,it);});
 furnaces.delete(k);
}
function tickFurnaces(dt){
 for(const f of furnaces.values()){
  const inp=f.slots[0],res=inp&&SMELT[inp.type],out=f.slots[2];
  const canRun=!!res&&(!out||(out.type===res&&out.count<64));
  const fuel=f.slots[1];
  if(f.burn<=0&&canRun&&fuel&&FUEL[fuel.type]){
   f.burn=f.burnMax=FUEL[fuel.type];
   if(--fuel.count<=0)f.slots[1]=null;
  }
  if(f.burn>0){
   f.burn-=dt;
   if(canRun){
    f.cook+=dt;
    if(f.cook>=10){
     f.cook=0;
     if(--inp.count<=0)f.slots[0]=null;
     if(out)out.count++;else f.slots[2]=createItem(res,1);
    }
   }else f.cook=0;
  }else f.cook=Math.max(0,f.cook-dt*2);
  if(f===curFurnace&&furnaceOpen)syncFurnace(false);
 }
}
function syncFurnace(force){
 const f=curFurnace;if(!f)return;
 [[fIn,0],[fFuel,1],[fOut,2]].forEach(([el,i])=>{
  const it=f.slots[i],sig=it?it.type+it.count+it.dur:'';
  if(force||el._sig!==sig){el._sig=sig;drawSlot(el,it);}
 });
 fBurn.style.width=(f.burnMax?Math.max(0,f.burn)/f.burnMax*100:0)+'%';
 fCook.style.width=(f.cook/10*100)+'%';
}
function renderFurnace(){
 furnInv.innerHTML='';furnHotbar.innerHTML='';
 inventoryItems.forEach((it,i)=>{const el=document.createElement('div');el.className='invSlot';el.dataset.index=i;drawSlot(el,it);furnInv.appendChild(el);});
 hotbar.forEach((it,i)=>{const el=document.createElement('div');el.className='invSlot';el.dataset.index=i;drawSlot(el,it);furnHotbar.appendChild(el);});
 syncFurnace(true);updateCursorItem();
}
function furnClick(i){
 const f=curFurnace;if(!f)return;
 if(i===2){
  const o=f.slots[2];
  if(o&&!cursorItem){cursorItem=o;f.slots[2]=null;}
  else if(o&&cursorItem.type===o.type&&cursorItem.count+o.count<=64){cursorItem.count+=o.count;f.slots[2]=null;}
 }else handleSlotClick(f.slots,i);
 renderInventory();renderFurnace();updateHotbar();
}
