function fillVillageChest(k,arr){
 if(!villageChestKeys.has(k))return;
 const [x,y,z]=k.split(',').map(Number),rng=mulberry(Math.imul(x,73856093)^Math.imul(y,19349663)^Math.imul(z,83492791));
 const table=[['emerald',1,4,.5],['leather',1,3,.3],['bread',2,4,.8],['wheat',2,5,.75],['seeds',2,4,.65],['iron_ingot',1,3,.55],['coal',2,6,.6],['diamond',1,1,.18],['iron_helmet',1,1,.12],['iron_boots',1,1,.12]];
 for(const [type,min,max,chance] of table){
  if(rng()>chance)continue;
  const slot=Math.floor(rng()*27),count=min+Math.floor(rng()*(max-min+1));
  arr[slot]=createItem(type,count);
 }
}
