const caneKeys=new Set();let caneTimer=0;
function caneOk(x,y,z){let yy=y-1;while(getBlock(x,yy,z)==='sugar_cane')yy--;if(!(getBlock(x,yy,z)==='sand'||DIRT_TYPES.has(getBlock(x,yy,z))||GRASS_TYPES.has(getBlock(x,yy,z))))return false;return [[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dz])=>getBlock(x+dx,yy,z+dz)==='water');}
function tickCane(dt){
 caneTimer-=dt;if(caneTimer>0)return;caneTimer=4;
 for(const k of [...caneKeys]){
  const [x,y,z]=k.split(',').map(Number);if(!canPlaceAt(x,y,z))continue;
  if(getBlock(x,y,z)!=='sugar_cane'){caneKeys.delete(k);continue;}
  let t=y;while(getBlock(x,t+1,z)==='sugar_cane')t++;
  if(t-y<2&&!getBlock(x,t+1,z)&&caneOk(x,y,z)&&Math.random()<.25)setBlockWorld(x,t+1,z,'sugar_cane');
 }
}
