const tradePanel=document.getElementById('tradePanel');
const countItem=t=>[...hotbar,...inventoryItems].reduce((n,it)=>n+(it&&it.type===t?it.count:0),0);
function takeItems(t,n){for(const arr of [hotbar,inventoryItems])for(let i=0;i<arr.length&&n>0;i++){const it=arr[i];if(it&&it.type===t){const a=Math.min(n,it.count);it.count-=a;n-=a;if(it.count<=0)arr[i]=null;}}}
function openTrade(v){
 playSound('villager',{vol:.8});
 pauseInput();tradeVillager=v;v.dir=Math.atan2(player.x-v.x,player.z-v.z);
 if(v.day!==dayNumber){v.day=dayNumber;v.uses={};}
 chestOpen=true;inventoryOpen=tableOpen=furnaceOpen=stonecutterOpen=false;curChest=null;
 [inventory,tableInventory,furnacePanel,chestPanel,stonecutterPanel].forEach(e=>e.style.display='none');tradePanel.style.display='block';
 if(pointerLocked)document.exitPointerLock();start.style.display='none';updateStartOverlay();renderTrade();
}
function renderTrade(){
 const v=tradeVillager;if(!v)return;
 document.getElementById('tradeTitle').textContent=cap(v.prof)+' — Trades';
 document.getElementById('tradeEm').textContent='Your emeralds: '+countItem('emerald');
 const list=document.getElementById('tradeList');list.innerHTML='';
 const stack=(t,n)=>{const d=document.createElement('span');d.className='tradeItem';const im=document.createElement('img');im.src=iconFor(t);d.append(im,document.createTextNode('×'+n+' '+itemName(t)));return d;};
 PROF[v.prof].t.forEach(([ins,out],idx)=>{
  const left=8-(v.uses[idx]||0),row=document.createElement('div');row.className='tradeRow';
  ins.forEach(([t,n])=>row.appendChild(stack(t,n)));
  const ar=document.createElement('span');ar.textContent='→';row.appendChild(ar);row.appendChild(stack(out[0],out[1]));
  const b=document.createElement('button');b.textContent=left>0?'Trade ('+left+' left)':'Sold out';
  b.disabled=left<=0||ins.some(([t,n])=>countItem(t)<n);b.onclick=()=>doTrade(idx);row.appendChild(b);list.appendChild(row);
 });
}
function doTrade(idx){
 const v=tradeVillager;if(!v)return;const [ins,out]=PROF[v.prof].t[idx];
 if((v.uses[idx]||0)>=8||ins.some(([t,n])=>countItem(t)<n))return;
 ins.forEach(([t,n])=>takeItems(t,n));
 if(!canFit(out[0],out[1])){ins.forEach(([t,n])=>addItem(t,n));showNotice('Make room in your inventory first.');renderTrade();return;}
 addItem(out[0],out[1]);v.uses[idx]=(v.uses[idx]||0)+1;gainXP(1);renderTrade();updateHotbar();renderInventory();
}
function villagerTarget(){
 camera.updateMatrixWorld();const d=new THREE.Vector3();camera.getWorldDirection(d);
 const ray=new THREE.Ray(camera.position,d),blk=getTarget();let dist=blk?camera.position.distanceTo(blk.point):4,best=null;
 for(const v of villagers){
  const box=new THREE.Box3(new THREE.Vector3(v.x-.45,v.feet,v.z-.45),new THREE.Vector3(v.x+.45,v.feet+1.9,v.z+.45));
  const p=ray.intersectBox(box,new THREE.Vector3());if(p){const n=camera.position.distanceTo(p);if(n<dist&&n<4){dist=n;best=v;}}
 }
 return best;
}
function dropChest(k,x=player.x,y=player.feet,z=player.z){
 const c=chests.get(k);if(!c)return;
 c.forEach(it=>{if(it)spawnWorldDrop(it.type,it.count,x+(Math.random()-.5)*.45,y+.35,z+(Math.random()-.5)*.45,it);});chests.delete(k);
}

// Every mined block becomes a physical pickup. The small toss, gravity,
// bounce, settling, spinning and proximity pickup mimic Minecraft item drops.
const droppedItems=[];
const dropMaterials=new Map();
function dropMaterialFor(type){
 let material=dropMaterials.get(type);
 if(!material){const texture=new THREE.TextureLoader().load(iconFor(type));texture.magFilter=THREE.NearestFilter;texture.minFilter=THREE.NearestFilter;material=new THREE.SpriteMaterial({map:texture,depthWrite:false});dropMaterials.set(type,material);}
 return material;
}
function spawnWorldDrop(type,count=1,x=player.x,y=player.feet+.7,z=player.z,obj=null,impulse=null){
 if(!type||count<=0)return null;
 const sprite=new THREE.Sprite(dropMaterialFor(type));sprite.scale.set(.34,.34,.34);
 const sx=x+(Math.random()-.5)*.18,sz=z+(Math.random()-.5)*.18,sy=y+.08;
 sprite.position.set(sx,sy,sz);scene.add(sprite);
 const kick=impulse||{};
 const drop={sprite,item:{...(obj||createItem(type,count)),type,count},delay:.28,age:0,
  vx:kick.vx??(Math.random()-.5)*1.9,vy:kick.vy??(2.2+Math.random()*1.0),vz:kick.vz??(Math.random()-.5)*1.9,
  grounded:false,bob:Math.random()*Math.PI*2,spin:(Math.random()-.5)*2.4};
  droppedItems.push(drop);
  if(mp&&mp.joined&&!mpNetSpawn&&type){
   const p=drop.sprite.position;drop.netId=mp.id+'.'+(++dropSeq);
   mpSend({t:'drop',id:drop.netId,type,count,x:p.x,y:p.y,z:p.z,vx:drop.vx,vy:drop.vy,vz:drop.vz,obj:obj?JSON.parse(JSON.stringify(obj)):null});
  }
  return drop;
}
function dropOverflow(type,count,obj){
 spawnWorldDrop(type,count,player.x,player.feet+.65,player.z,obj,{vy:1.7});
 showNotice('Inventory full — extra items are on the ground.');
}
function dropSelectedItem(){
 const held=hotbar[selected];if(!held)return;
 const item={...held,count:1};if(gameMode!=='creative'&&--held.count<=0)hotbar[selected]=null;
 const direction=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw));
 const x=player.x+direction.x*1.6,z=player.z+direction.z*1.6,y=player.feet+.55;
 spawnWorldDrop(item.type,1,x,y,z,item,{vx:direction.x*2.4,vy:2.0,vz:direction.z*2.4});
 updateHotbar();renderInventory();showNotice('Dropped 1 '+itemName(item.type)+'.');
}
function disposeDropAt(i){const d=droppedItems[i];if(!d)return;scene.remove(d.sprite);droppedItems.splice(i,1);}
function tickDrops(dt){
 for(let i=droppedItems.length-1;i>=0;i--){
  const d=droppedItems[i],p=d.sprite.position;d.delay-=dt;d.age+=dt;d.bob+=dt*3.2;
  if(!d.grounded){
   d.vy-=13.5*dt;d.vx*=Math.pow(.985,dt*60);d.vz*=Math.pow(.985,dt*60);
   const nx=p.x+d.vx*dt,nz=p.z+d.vz*dt;let ny=p.y+d.vy*dt;
   const bx=Math.round(nx),bz=Math.round(nz),by=Math.floor(ny-.5),support=getBlock(bx,by,bz);
   if(support&&support!=='water'&&OPAQUE[ID[support]]){
    const restY=by+.69;
    if(ny<=restY&&d.vy<0){ny=restY;d.vy=-d.vy*.27;d.vx*=.58;d.vz*=.58;if(d.vy<.72){d.vy=0;d.grounded=true;}}
   }
   p.set(nx,ny,nz);
  }else p.y+=Math.sin(d.bob)*.012;
  d.sprite.rotation.z+=d.spin*dt;
  const it=d.item;
  const near=d.delay<=0&&Math.hypot(player.x-p.x,player.z-p.z)<1.35&&Math.abs((player.feet+.35)-p.y)<1.85;
  if(d.netId&&mp&&mp.joined){
   if(d.pending){d.pendingT-=dt;if(d.pendingT<=0)d.pending=false;}
   else if(near&&canFit(it.type,it.count)){d.pending=true;d.pendingT=3;mpSend({t:'pickup',id:d.netId});}
   if(d.age>180)disposeDropAt(i);
  }else if(near&&canFit(it.type,it.count)){
   const taken={...it};disposeDropAt(i);addItem(taken.type,taken.count,taken);
  }else if(d.age>180){disposeDropAt(i);}
 }
}

/* ================= FALLING LEAVES ================= */
const LEAF_PARTICLE_TEXTURES={
 oak:makeTexture(ctx=>{ctx.clearRect(0,0,16,16);ctx.fillStyle='#2f742b';ctx.fillRect(7,2,4,12);ctx.fillStyle='#65ad45';ctx.fillRect(4,4,8,7);ctx.fillStyle='#9ccc65';ctx.fillRect(6,5,4,4);ctx.fillStyle='#7b9c45';ctx.fillRect(9,13,1,2);}),
 birch:makeTexture(ctx=>{ctx.clearRect(0,0,16,16);ctx.fillStyle='#568c36';ctx.fillRect(7,2,4,12);ctx.fillStyle='#a7d36b';ctx.fillRect(4,4,8,7);ctx.fillStyle='#d5ec9b';ctx.fillRect(6,5,4,4);}),
 spruce:makeTexture(ctx=>{ctx.clearRect(0,0,16,16);ctx.fillStyle='#173e2b';ctx.fillRect(7,2,4,12);ctx.fillStyle='#34764a';ctx.fillRect(4,4,8,7);ctx.fillStyle='#75a35a';ctx.fillRect(6,5,4,4);}),
 jungle:makeTexture(ctx=>{ctx.clearRect(0,0,16,16);ctx.fillStyle='#246438';ctx.fillRect(7,2,4,12);ctx.fillStyle='#54a34a';ctx.fillRect(4,4,8,7);ctx.fillStyle='#a1cd63';ctx.fillRect(6,5,4,4);}),
 pink:makeTexture(ctx=>{ctx.clearRect(0,0,16,16);ctx.fillStyle='#9d4a8e';ctx.fillRect(7,2,4,12);ctx.fillStyle='#e58acb';ctx.fillRect(4,4,8,7);ctx.fillStyle='#ffe0f5';ctx.fillRect(6,5,4,4);}),
 purple:makeTexture(ctx=>{ctx.clearRect(0,0,16,16);ctx.fillStyle='#583a89';ctx.fillRect(7,2,4,12);ctx.fillStyle='#9871c9';ctx.fillRect(4,4,8,7);ctx.fillStyle='#ead7ff';ctx.fillRect(6,5,4,4);})
};
const leafParticleMats=Object.fromEntries(Object.entries(LEAF_PARTICLE_TEXTURES).map(([k,t])=>[k,new THREE.SpriteMaterial({map:t,transparent:true,depthWrite:false})]));
const leafTypeToPalette={leaves:'oak',birch_leaves:'birch',spruce_leaves:'spruce',jungle_leaves:'jungle',pink_leaves:'pink',purple_leaves:'purple'};
const leafParticles=[];let leafEmitClock=0;
function spawnLeafParticle(x,y,z,type){
 const palette=leafTypeToPalette[type]||'oak',sprite=new THREE.Sprite(leafParticleMats[palette]);
 const size=.16+Math.random()*.13;sprite.scale.set(size,size*1.35,1);
 sprite.position.set(x,y,z);sprite.material.rotation=0;scene.add(sprite);
 leafParticles.push({sprite,vx:(Math.random()-.5)*.48,vy:-.15-Math.random()*.35,vz:(Math.random()-.5)*.48,age:0,life:4.5+Math.random()*3,phase:Math.random()*6.28,spin:(Math.random()-.5)*3});
}
function tickLeafParticles(dt){
 for(let i=leafParticles.length-1;i>=0;i--){
  const p=leafParticles[i],v=p.sprite.position;p.age+=dt;p.phase+=dt*2.1;
  p.vx+=Math.sin(p.phase)*.10*dt;p.vz+=Math.cos(p.phase*.83)*.10*dt;p.vy-=.28*dt;
  v.x+=p.vx*dt;v.y+=p.vy*dt;v.z+=p.vz*dt;p.sprite.rotation.z+=p.spin*dt;
  const belowSurface=heightAt(Math.round(v.x),Math.round(v.z))+.45;
  if(p.age>p.life||v.y<belowSurface||Math.hypot(player.x-v.x,player.z-v.z)>32){scene.remove(p.sprite);leafParticles.splice(i,1);}
 }
 if(!started||menuOpen||!inGame||leafParticles.length>=32)return;
 leafEmitClock+=dt;if(leafEmitClock<.2)return;leafEmitClock=0;
 // Search a few nearby columns for actual canopy blocks. This is deliberately
 // sparse and local so the effect stays cheap in the infinite chunk world.
 for(let attempt=0;attempt<7&&leafParticles.length<32;attempt++){
  const angle=Math.random()*Math.PI*2,dist=3+Math.random()*14;
  const x=Math.round(player.x+Math.cos(angle)*dist),z=Math.round(player.z+Math.sin(angle)*dist);
  const surface=heightAt(x,z);let found=null;
  const yStart=surface+2+Math.floor(Math.random()*5),yEnd=surface+18;
  for(let y=yStart;y<=yEnd;y++){
   const t=getBlock(x,y,z);if(leafTypeToPalette[t]){found={y,type:t};break;}
  }
  if(found&&Math.random()<.62)spawnLeafParticle(x+(Math.random()-.5)*.45,found.y+.35,z+(Math.random()-.5)*.45,found.type);
 }
}
function clearLeafParticles(){for(const p of leafParticles)scene.remove(p.sprite);leafParticles.length=0;leafEmitClock=0;}

