// Blocks are held as real 3D cubes; everything else becomes a thick pixel sprite built from its inventory icon.
function heldBlockMats(type){
 if(/^flower_|_sapling$|trapdoor$/.test(type)||FENCE_OF[type]||['ladder','sign','sugar_cane','tall_grass','wheat_crop','torch','fence','bed','lantern','glass_pane'].includes(type)||type.startsWith('cushion'))return null;
 if(type==='chest')return materials.chest0;
 const sh=SHP[type];return materials[sh?sh[0]:type]||null;
}
function buildHeldModel(type,done){
 const mats=heldBlockMats(type);
 if(mats){
  const sk=SHP[type]?.[1],g=new THREE.Group();
  const add=(w,h,d,x,y,z)=>{const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mats);m.position.set(x,y,z);g.add(m);};
  if(sk==='slab')add(1,.5,1,0,-.25,0);
  else if(sk==='stairs'){add(1,.5,1,0,-.25,0);add(1,.5,.5,0,.25,-.25);}
  else add(1,1,1,0,0,0);
  done(g,true);return;
 }
 const img=new Image();
 img.onload=()=>{
  const c=document.createElement('canvas');c.width=c.height=32;
  const cx=c.getContext('2d');cx.drawImage(img,0,0,32,32);
  const d=cx.getImageData(0,0,32,32).data,pts=[];
  for(let y=0;y<32;y++)for(let x=0;x<32;x++){const i=(y*32+x)*4;if(d[i+3]>100)pts.push([x,y,d[i],d[i+1],d[i+2]]);}
  if(!pts.length)return;
  const S=.62/32,T=S*2.2;
  const mesh=new THREE.InstancedMesh(new THREE.BoxGeometry(1,1,1),new THREE.MeshLambertMaterial(),pts.length);
  const m4=new THREE.Matrix4(),col=new THREE.Color();
  pts.forEach(([x,y,r,gg,b],i)=>{
   m4.makeScale(S,S,T).setPosition((x-15.5)*S,(15.5-y)*S,0);
   mesh.setMatrixAt(i,m4);col.setRGB(r/255,gg/255,b/255,THREE.SRGBColorSpace);mesh.setColorAt(i,col);
  });
  mesh.instanceMatrix.needsUpdate=true;mesh.instanceColor.needsUpdate=true;mesh.frustumCulled=false;
  const g=new THREE.Group();g.add(mesh);done(g,false);
 };
 img.src=iconFor(type);
}
function placeHeld(mount,g,cfg){g.scale.setScalar(cfg.s);g.position.set(...cfg.pos);g.rotation.set(...cfg.rot);mount.add(g);}
function refreshHeld(){
 const it=hotbar[selected],type=it?it.type:'';
 if(type===heldSig)return;
 heldSig=type;equipT=0;const gen=++heldGen;
 clearHeld(fpMount);clearHeld(heldTP);
 if(!type)return;
 buildHeldModel(type,(g,b)=>{if(gen===heldGen)placeHeld(fpMount,g,b?HELD_FP.block:HELD_FP.item);});
 buildHeldModel(type,(g,b)=>{if(gen===heldGen)placeHeld(heldTP,g,b?HELD_TP.block:HELD_TP.item);});
}
function updateHand(dt){
 handVisible=viewMode===0&&started&&!menuOpen&&!survival.dead&&sleepTimer<=0;
 refreshHeld();
 const spd=Math.hypot(player.x-lastHX,player.z-lastHZ)/Math.max(dt,.001);lastHX=player.x;lastHZ=player.z;
 const walk=Math.min(1,spd/5.5)*(player.grounded?1:.3);bobT+=Math.min(spd,9)*dt*1.9;
 equipT=Math.min(1,equipT+dt*5);
 if(swingP>=0){swingP+=dt/.3;if(swingP>=1)swingP=-1;}
 if(viewMode>0&&swingP>=0)mArmR.p.rotation.x=1.5*Math.sin(swingP*Math.PI);
 if(!handVisible)return;
 const sw=swingP>=0?Math.sin(swingP*Math.PI):0,sq=swingP>=0?Math.sin(Math.sqrt(swingP)*Math.PI):0,eq=1-equipT;
 handRig.position.set(Math.sin(bobT)*.014*walk,-Math.abs(Math.cos(bobT))*.022*walk-eq*eq*.55,0);
 handArm.position.set(HAND_BASE.x,HAND_BASE.y+sw*.07,HAND_BASE.z-sw*.1);
 handArm.rotation.set(HAND_BASE.rx-sw*.6,HAND_BASE.ry-sq*.35,HAND_BASE.rz+sq*.15);
 const chest=armorSlots[1]?PAL[armorSlots[1].type.split('_')[0]]?.[0]:null;
 handSleeveMat.color.set(chest||SHIRT);
 handHemi.intensity=.85+1.25*daylight;handSun.intensity=.3+.9*daylight;
}

