/* ================= MINING / PLACING ================= */

const raycaster=new THREE.Raycaster();
raycaster.far=6;
const center=new THREE.Vector2(0,0);

let target=null,mining=false,mineProgress=0;

const outline=new THREE.LineSegments(
 new THREE.EdgesGeometry(blockGeo),
 new THREE.LineBasicMaterial({color:0xffffff})
);
outline.scale.setScalar(1.003);
outline.visible=false;
scene.add(outline);

function getTarget(){
 const o=camera.position,d=new THREE.Vector3();camera.getWorldDirection(d);
 const dd=[d.x,d.y,d.z],oo=[o.x,o.y,o.z],c=oo.map(Math.round),st=dd.map(Math.sign);
 const tMax=[],tDelta=[];
 for(let i=0;i<3;i++){
  if(dd[i]===0){tMax[i]=Infinity;tDelta[i]=Infinity;}
  else{tMax[i]=(c[i]+(st[i]>0?.5:-.5)-oo[i])/dd[i];tDelta[i]=Math.abs(1/dd[i]);}
 }
 const mk=(type,nn,distance=t)=>({object:{userData:{x:c[0],y:c[1],z:c[2],type},position:new THREE.Vector3(c[0],c[1],c[2])},face:{normal:new THREE.Vector3(...nn)},point:o.clone().addScaledVector(d,Math.max(0,distance))});
 let n=[0,0,0],t=0;
 while(t<=6){
  const type=getBlock(c[0],c[1],c[2]);
  if(type&&type!=='water'){
   const bx=blockBoxes(type,getMeta(c[0],c[1],c[2]),c[0],c[1],c[2]);
   if(!bx)return mk(type,n);
   let best=null;
   for(const b of bx){
    let tn=-Infinity,tf=Infinity,ax=-1,sg=0,miss=false;
    for(let i=0;i<3&&!miss;i++){
     const lo=c[i]+b[i],hi=c[i]+b[i+3];
     if(dd[i]===0){if(oo[i]<lo||oo[i]>hi)miss=true;continue;}
     let t1=(lo-oo[i])/dd[i],t2=(hi-oo[i])/dd[i],sgn=-1;
     if(t1>t2){const q=t1;t1=t2;t2=q;sgn=1;}
     if(t1>tn){tn=t1;ax=i;sg=sgn;}
     if(t2<tf)tf=t2;
    }
    if(!miss&&tn<=tf&&tf>=0&&tn<=6&&(!best||tn<best.t))best={t:tn,ax,sg};
   }
   if(best){const nn=[0,0,0];if(best.ax>=0)nn[best.ax]=best.sg;return mk(type,nn,best.t);}
  }
  const a=tMax[0]<tMax[1]?(tMax[0]<tMax[2]?0:2):(tMax[1]<tMax[2]?1:2);
  t=tMax[a];c[a]+=st[a];tMax[a]+=tDelta[a];n=[0,0,0];n[a]=-st[a];
 }
 return null;
}

function targetBlock(){
 const hit=getTarget();
 if(hit){
  target=hit.object;
  const {x,y,z,type}=target.userData,boxes=blockBoxes(type,getMeta(x,y,z),x,y,z);
  if(boxes){
   const lo=[0,1,2].map(i=>Math.min(...boxes.map(b=>b[i]))),hi=[0,1,2].map(i=>Math.max(...boxes.map(b=>b[i+3])));
   outline.position.set(x+(lo[0]+hi[0])/2,y+(lo[1]+hi[1])/2,z+(lo[2]+hi[2])/2);
   outline.scale.set((hi[0]-lo[0])*1.003,(hi[1]-lo[1])*1.003,(hi[2]-lo[2])*1.003);
  }else{outline.position.copy(target.position);outline.scale.setScalar(1.003);}
  outline.visible=true;
 }else{
  target=null;
  outline.visible=false;
 }
}

document.addEventListener('mousedown',e=>{
 if(menuOpen||!started||inventoryOpen||tableOpen||furnaceOpen||chestOpen||stonecutterOpen||signOpen)return;

 if(touchMode||!pointerLocked)return;

 if(survival.dead||sleepTimer>0)return;
 if(e.button===0){
  mining=true;
  if(attackMob())return;
  mineProgress=0;
 }

 if(e.button===2){
  // Place/use exactly once per right-click.
  mining=false;
  const vt=villagerTarget();if(vt){openTrade(vt);return;}
  placeOrUseBlock();
 }
});

document.addEventListener('mouseup',e=>{
 if(e.button===0){mining=false;mineProgress=0;}
});

document.addEventListener('contextmenu',e=>e.preventDefault());

let mineKey='';
function breakInfo(type){
 if(gameMode==='creative')return {t:.075,harvest:true};
 const d=BLOCKS[type],it=hotbar[selected],tl=it&&ITEMS[it.type];
 const ok=d.t==='none'||(!!tl&&tl.tool===d.t);
 const harvest=!d.need||(ok&&tl.lv>=d.need);
 return{t:Math.max(.1,d.h*(harvest?1.5:5)/(ok?tl.speed:1)),harvest};
}

function damageHeldTool(n=1){
 if(gameMode==='creative')return false;
 const it=hotbar[selected];if(!it||!ITEMS[it.type]?.tool)return false;
 if((it.dur-=n)<=0){hotbar[selected]=null;playSound('toolbreak',{vol:.9});}
 updateHotbar();renderInventory();return true;
}
const ORE_XP={coal_ore:1,iron_ore:2,diamond_ore:6,rhinestone_ore:7,emerald_ore:5};
function mine(dt){
 if(mining&&attackMob()){mineProgress=0;mineKey='';return;}
 if(!mining||!target){mineProgress=0;mineKey='';outline.material.color.set(0xffffff);return;}
 const {x,y,z,type}=target.userData,k=key(x,y,z);
 if(k!==mineKey){mineKey=k;mineProgress=0;}
 mineProgress+=dt;
 const b=breakInfo(type),p=Math.min(1,mineProgress/b.t);
 outline.material.color.setRGB(1,1-p,1-p);
 if(mineProgress>=b.t){
  const oldMeta=getMeta(x,y,z);
  const dropAt=(dropType,count=1,obj=null)=>spawnWorldDrop(dropType,count,x+(Math.random()-.5)*.25,y+.25,z+(Math.random()-.5)*.25,obj);
  if(type==='oak_sapling'||type==='birch_sapling'||type==='spruce_sapling')saplingKeys.delete(k);
  removeBlock(x,y,z);breakDependents(x,y,z);
  if(type==='furnace'){if(gameMode==='creative')furnaces.delete(key(x,y,z));else dropFurnace(key(x,y,z),x,y,z);}
  if(type==='sign')signs.delete(key(x,y,z));
  if(type==='chest'){villageChestKeys.delete(key(x,y,z));if(gameMode==='creative')chests.delete(key(x,y,z));else dropChest(key(x,y,z),x,y,z);}
  if(type==='bed_foot'||type==='bed_head'){
   const [dx,dz]=bedDirection(oldMeta),sign=type==='bed_foot'?1:-1;
   removeBlock(x+dx*sign,y,z+dz*sign);
  }
  if(DOOR_BLOCKS.has(type)&&type.endsWith('door_bottom'))removeBlock(x,y+1,z);
  if(DOOR_BLOCKS.has(type)&&type.endsWith('door_top'))removeBlock(x,y-1,z);
  {const above=getBlock(x,y+1,z);
   if(above&&DOOR_BLOCKS.has(above)&&above.endsWith('door_bottom')){
    removeBlock(x,y+1,z);removeBlock(x,y+2,z);if(gameMode!=='creative')dropAt(BLOCKS[above].drop,1);
   }}
  if(type==='farmland'&&getBlock(x,y+1,z)==='wheat_crop'){
   const m=getMeta(x,y+1,z);removeBlock(x,y+1,z);cropKeys.delete(key(x,y+1,z));
   if(gameMode!=='creative'){if(m>=3)dropAt('wheat',1);dropAt('seeds',1);}
  }
  if(type==='wheat_crop'){
   cropKeys.delete(k);
   if(gameMode!=='creative'){if(oldMeta>=3){dropAt('wheat',1);dropAt('seeds',1+(Math.random()<.5?1:0));gainXP(1);}
   else dropAt('seeds',1);}
  }else if(type==='tall_grass'){
   if(gameMode!=='creative'&&Math.random()<.7)dropAt('seeds',1);
  }else if((type==='leaves'||type==='birch_leaves'||type==='spruce_leaves'||type==='jungle_leaves'||type==='pink_leaves'||type==='purple_leaves')&&gameMode!=='creative'){
   if(Math.random()<.05){const sap=type==='birch_leaves'?'birch_sapling':type==='spruce_leaves'?'spruce_sapling':type==='jungle_leaves'?'oak_sapling':type==='pink_leaves'?'oak_sapling':type==='purple_leaves'?'oak_sapling':'oak_sapling';dropAt(sap,1);}
   if(b.harvest)dropAt(type,1);
  }else if(b.harvest&&gameMode!=='creative'){
   let dropT=BLOCKS[type].drop||type;if((type==='bed_foot'||type==='bed_head')&&(oldMeta>>4))dropT='bed_'+DYE_NAMES[(oldMeta>>4)-1];
   dropAt(dropT,BLOCKS[type].count||1);
   if(type==='pot'&&oldMeta>0&&oldMeta<=DYE_NAMES.length)dropAt('flower_'+DYE_NAMES[oldMeta-1],1);
   if((GRASS_TYPES.has(type))&&Math.random()<.32)dropAt('seeds',1);
   if(ORE_XP[type])gainXP(ORE_XP[type]);
  }
  if(getBlock(x,y+1,z)==='sugar_cane'){let yy=y+1;while(getBlock(x,yy,z)==='sugar_cane'){removeBlock(x,yy,z);if(gameMode!=='creative')dropAt('sugar_cane',1);yy++;}}
  if(gameMode!=='creative')damageHeldTool();
  target=null;outline.visible=false;mineProgress=0;mineKey='';
 }
}

const facing=()=>((Math.round(yaw/(Math.PI/2))%4)+4)%4;
function canPlaceAt(x,y,z){
 return y>=MIN_Y&&y<MIN_Y+HT&&chunks.has(ck(Math.floor(x/CS),Math.floor(z/CS)));
}
function supportsDoor(x,y,z){
 const type=getBlock(x,y,z);if(!type||type==='water'||type==='torch'||type==='wheat_crop'||type==='tall_grass'||type==='sugar_cane'||type.startsWith('flower_'))return false;
 const boxes=blockBoxes(type,getMeta(x,y,z));
 return !boxes||boxes.some(b=>b[0]===-.5&&b[2]===-.5&&b[3]===.5&&b[5]===.5&&b[4]===.5);
}
function consumeSelected(){
 if(gameMode==='creative')return;
 const item=hotbar[selected];if(--item.count<=0)hotbar[selected]=null;
 updateHotbar();renderInventory();
}
function toggleDoor(x,y,z){
 const t=getBlock(x,y,z),low=t.endsWith('door_bottom'),pre=t.slice(0,t.indexOf('door_')),oy=low?y+1:y-1,ot=pre+(low?'door_top':'door_bottom');
 const nm=getMeta(x,y,z)^4;
 if(hitBoxes(player.x,player.feet,player.z,x,y,z,blockBoxes(t,nm))||hitBoxes(player.x,player.feet,player.z,x,oy,z,blockBoxes(ot,nm)))return;
 setBlockWorld(x,y,z,t,nm);setBlockWorld(x,oy,z,ot,nm);playSound('door',{vol:.8});
}

function toggleTrapdoor(x,y,z){
 const tt=getBlock(x,y,z),nm=getMeta(x,y,z)^4;
 if(hitBoxes(player.x,player.feet,player.z,x,y,z,blockBoxes(tt,nm)))return;
 setBlockWorld(x,y,z,tt,nm);playSound('door',{vol:.7,rate:1.15});
}
// First water cell along the view ray that is in front of any solid block.
function getWaterTarget(hit){
 const o=camera.position,d=new THREE.Vector3();camera.getWorldDirection(d);
 const max=hit?Math.min(6,o.distanceTo(hit.point)):5;
 for(let t=0;t<=max;t+=.05){
  const x=Math.round(o.x+d.x*t),y=Math.round(o.y+d.y*t),z=Math.round(o.z+d.z*t);
  if(getBlock(x,y,z)==='water')return{x,y,z};
 }
 return null;
}
// Bucket handling: scoop up still water, or pour a water bucket out.
function useBucket(hit,held){
 if(held.type==='bucket'){
  const w=getWaterTarget(hit);
  if(!w)return false;
  if(getMeta(w.x,w.y,w.z)&7){showNotice('Only still water can be collected — find a source block.');return true;}
  setBlockWorld(w.x,w.y,w.z,null);
  if(--held.count<=0)hotbar[selected]=createItem('water_bucket',1);
  else addItem('water_bucket',1);
  updateHotbar();renderInventory();playSound('splash',{vol:.6,dur:1.4,rate:1.1});showNotice('Bucket filled with water.');
  return true;
 }
 if(!hit)return false;
 const {x,y,z}=hit.object.userData,n=hit.face.normal;
 const bx=x+Math.round(n.x),by=y+Math.round(n.y),bz=z+Math.round(n.z),t=getBlock(bx,by,bz);
 if(!canPlaceAt(bx,by,bz))return true;
 if(t&&t!=='water'&&t!=='tall_grass'&&!t.startsWith('flower_')){showNotice('There is no room to pour water here.');return true;}
 if(t==='water'&&!(getMeta(bx,by,bz)&7)){showNotice('That spot is already full of water.');return true;}
 setBlockWorld(bx,by,bz,'water',0);queueWaterAround(bx,by,bz);playSound('splash',{vol:.6,dur:1.4,rate:1.1});
 hotbar[selected]=createItem('bucket',1);
 updateHotbar();renderInventory();
 return true;
}
/* ================= BOW & ARROWS ================= */
const playerArrows=[];let bowCooldown=0;
function countArrows(){let n=0;for(const arr of [hotbar,inventoryItems])for(const it of arr)if(it&&it.type==='arrow')n+=it.count;return n;}
function fireBow(bow){
 if(bowCooldown>0)return;
 const creative=gameMode==='creative';
 if(!creative&&!countArrows()){showNotice('You need arrows to shoot the bow.');return;}
 if(!creative){takeItems('arrow',1);if((bow.dur-=1)<=0){hotbar[selected]=null;playSound('toolbreak',{vol:.9});}updateHotbar();renderInventory();}
 bowCooldown=.55;
 camera.updateMatrixWorld();const d=new THREE.Vector3();camera.getWorldDirection(d);
 const origin=camera.position.clone().addScaledVector(d,.6);origin.y-=.12;
 const group=new THREE.Group();
 hostileCube(group,.05,.05,.62,0,0,0,arrowMat);hostileCube(group,.13,.04,.13,0,0,-.26,bowMat);hostileCube(group,.07,.07,.1,0,0,.33,boneShadeMat);
 group.position.copy(origin);group.lookAt(origin.clone().add(d));scene.add(group);
 playerArrows.push({group,pos:origin,vel:d.multiplyScalar(30),life:5});
}
function tickPlayerArrows(dt){
 bowCooldown=Math.max(0,bowCooldown-dt);
 for(let i=playerArrows.length-1;i>=0;i--){
  const a=playerArrows[i];a.life-=dt;let done=a.life<=0;
  for(let st=0;st<4&&!done;st++){
   const h=dt/4;a.vel.y-=9*h;a.pos.addScaledVector(a.vel,h);
   const block=getBlock(Math.round(a.pos.x),Math.round(a.pos.y),Math.round(a.pos.z));
   if(block&&!['water','torch','wheat_crop','tall_grass','sugar_cane','sign'].includes(block)&&!block.startsWith('flower_')&&!block.endsWith('_sapling')){
    const bx=blockBoxes(block,getMeta(Math.round(a.pos.x),Math.round(a.pos.y),Math.round(a.pos.z)));
    if(!bx||bx.length)done=true;
   }
   for(const m of [...animals,...zombies,...skeletons,...spiders]){
    const hh=m.targetHeight??(m.hostile?1.95:1.25),w=(m.targetWidth??(m.hostile?.55:.5))+.1,dp=(m.targetDepth??(m.hostile?.5:.6))+.1;
    if(Math.abs(a.pos.x-m.x)<w&&Math.abs(a.pos.z-m.z)<dp&&a.pos.y>m.feet&&a.pos.y<m.feet+hh){hurtMob(m,6);done=true;break;}
   }
  }
  a.group.position.copy(a.pos);a.group.lookAt(a.pos.clone().add(a.vel));
  if(done){scene.remove(a.group);playerArrows.splice(i,1);}
 }
}
// Wall torches, standing torches/lanterns and hanging lanterns fall off when their support is mined away.
function breakDependents(x,y,z){
 const drop=(t,px,py,pz)=>{removeBlock(px,py,pz);if(gameMode!=='creative')spawnWorldDrop(t,1,px,py+.3,pz);};
 const up=getBlock(x,y+1,z)||'',dn=getBlock(x,y-1,z)||'';
 if((up==='torch'||up==='lantern')&&!(getMeta(x,y+1,z)&4))drop(up,x,y+1,z);
 if(dn==='lantern'&&(getMeta(x,y-1,z)&4))drop('lantern',x,y-1,z);
 if(up.startsWith('cushion'))drop(up,x,y+1,z);
 [[0,1],[1,0],[0,-1],[-1,0]].forEach(([wx,wz],lm)=>{const tx=x-wx,tz=z-wz;
  if(getBlock(tx,y,tz)==='torch'){const m=getMeta(tx,y,tz);if((m&4)&&(m&3)===lm)drop('torch',tx,y,tz);}});
}
let sitting=null;
function standUp(){if(!sitting)return;sitting=null;}
function sitDown(x,y,z){
 if(sitting||Math.hypot(x-player.x,z-player.z)>3.5)return;
 const low=getMeta(x,y,z)&4;
 sitting={x,y,z};player.x=x;player.z=z;player.feet=y+(low?-.8:-.3);player.vy=0;player.grounded=true;
 showNotice('Sitting — move or jump to stand up.');
}
function usePot(x,y,z,held){
 const meta=getMeta(x,y,z);
 if(!meta&&held&&held.type.startsWith('flower_')&&DYE_NAMES.includes(held.type.slice(7))){
  setBlockWorld(x,y,z,'pot',DYE_NAMES.indexOf(held.type.slice(7))+1);
  if(gameMode!=='creative'){held.count--;if(held.count<=0)hotbar[selected]=null;updateHotbar();}
  playSound('click',{vol:.6});return true;
 }
 if(meta&&!held){
  setBlockWorld(x,y,z,'pot',0);
  if(gameMode!=='creative')spawnWorldDrop('flower_'+DYE_NAMES[meta-1],1,x,y+.4,z);
  return true;
 }
 return false;
}
function placeOrUseBlock(){
 if(survival.dead||sleepTimer>0)return;
 kickSwing();
 const hit=getTarget(),held=hotbar[selected];
 const hitType=hit?.object.userData.type;
 const interactive=['crafting_table','furniture_table','stonecutter','furnace','chest','sign','bed_foot','bed_head',...DOOR_BLOCKS,...TRAP_TYPES];
 if(held?.type==='bow'&&!interactive.includes(hitType)){fireBow(held);return;}
 if((held?.type==='bucket'||held?.type==='water_bucket')&&!interactive.includes(hitType)&&useBucket(hit,held))return;
 if(!hit){
  if(held?.type==='fairy_dust'){
   if(backSlot?.type==='fairy_wings'){consumeSelected();fairyFlightTimer=10;player.vy=Math.max(player.vy,1.2);showNotice('Fairy wings powered for 10 seconds! Hold Space to rise, Shift to glide down.');}
   else showNotice('Equip Fairy Wings in your Back slot first.');
   return;
  }
  if(FOOD[held?.type])eatFood();return;
 }

 const hitBlock=hit.object;
 const {x,y,z,type}=hitBlock.userData;

 // Right-click crafting table to open its 3x3 grid.
 if(type==='crafting_table'){
  openTable();
  return;
 }
 if(type==='furnace'){
  openFurnace(key(x,y,z));
  return;
 }
 if(type==='furniture_table'){openTable('furniture');return;}
 if(type==='stonecutter'){openStonecutter();return;}

 if(type.startsWith('cushion')){sitDown(x,y,z);return;}
 if(type==='pot'&&usePot(x,y,z,held))return;
 if(DOOR_BLOCKS.has(type)){toggleDoor(x,y,z);return;}
 if(TRAP_TYPES.has(type)){toggleTrapdoor(x,y,z);return;}
 if(type==='chest'){openChest(key(x,y,z));return;}
 if(type==='sign'){openSign(key(x,y,z));return;}
 if(type==='bed_foot'||type==='bed_head'){useBed(x,y,z);return;}
 if(type==='wheat_crop'){
  if(getMeta(x,y,z)>=3){
   removeBlock(x,y,z);cropKeys.delete(key(x,y,z));addItem('wheat',1);addItem('seeds',1+(Math.random()<.5?1:0));gainXP(1);
  }else showNotice('This wheat is still growing.');
  return;
 }
 const tool=held&&ITEMS[held.type]?.tool;
 const stripTo={log:'stripped_log',birch_log:'stripped_birch_log',spruce_log:'stripped_spruce_log'};
 if(stripTo[type]&&tool==='axe'){
  if(setBlockWorld(x,y,z,stripTo[type],getMeta(x,y,z))){damageHeldTool();showNotice('Stripped '+(type==='log'?'oak':type==='birch_log'?'birch':'spruce')+' log.');}
  return;
 }
 if((GRASS_TYPES.has(type)||DIRT_TYPES.has(type))&&tool==='shovel'){
  if(setBlockWorld(x,y,z,'path')){damageHeldTool();showNotice('Dirt path created.');}
  return;
 }
 if((GRASS_TYPES.has(type)||DIRT_TYPES.has(type))&&tool==='hoe'){
  if(setBlockWorld(x,y,z,'farmland')){damageHeldTool();showNotice('Farmland tilled — plant seeds on it.');}
  return;
 }
 if(type==='farmland'&&held?.type==='seeds'){
  if(getBlock(x,y+1,z)){showNotice('There is no room to plant here.');return;}
  if(setBlockWorld(x,y+1,z,'wheat_crop',0)){cropKeys.add(key(x,y+1,z));consumeSelected();showNotice('Wheat planted.');}
  return;
 }
 if(FOOD[held?.type]){eatFood();return;}

 const item=hotbar[selected];
 if(!item||!(BLOCKS[item.type]||DOOR_ITEMS[item.type]||item.type==='bed'||item.type.startsWith('bed_')))return;

 const normal=hit.face.normal;
 let bx=x+Math.round(normal.x),by=y+Math.round(normal.y),bz=z+Math.round(normal.z);
 if(item.type==='ladder'){
  // Ladders hang on the side of a solid block. Clicking a ladder extends it up (or down when looking down).
  let lm,ok;
  if(type==='ladder'){
   lm=getMeta(x,y,z)&3;bx=x;bz=z;
   by=y+(pitch<-.35?-1:1);
   while(getBlock(bx,by,bz)==='ladder'&&Math.abs(by-y)<6)by+=pitch<-.35?-1:1;
  }else{
   if(normal.y!==0||!OPAQUE[ID[type]]){showNotice('Ladders attach to the side of a solid block.');return;}
   lm={'0,1':2,'0,-1':0,'1,0':3,'-1,0':1}[Math.round(normal.x)+','+Math.round(normal.z)];
  }
  const [wx,wz]=[[0,1],[1,0],[0,-1],[-1,0]][lm];
  ok=!!OPAQUE[getId(bx+wx,by,bz+wz)];
  if(!ok){showNotice('Ladders need a solid block behind them.');return;}
  if(!canPlaceAt(bx,by,bz)||(getBlock(bx,by,bz)&&getBlock(bx,by,bz)!=='water'))return;
  if(hitBoxes(player.x,player.feet,player.z,bx,by,bz,blockBoxes('ladder',lm)))return;
  if(addBlock(bx,by,bz,'ladder',lm))consumeSelected();
  return;
 }
 // Clicking the free half of a slab combines two slabs into one full block.
 if(SHP[item.type]?.[1]==='slab'){
  const same=type===item.type&&((!(getMeta(x,y,z)&4)&&normal.y>0)||((getMeta(x,y,z)&4)&&normal.y<0));
  if(same){bx=x;by=y;bz=z;}
  if(getBlock(bx,by,bz)===item.type){
   const top=!!(getMeta(bx,by,bz)&4),placeTop=normal.y<0||(normal.y===0&&hit.point.y-y>0);
   if(!same&&(normal.y!==0||top===placeTop))return;
   if(hitBoxes(player.x,player.feet,player.z,bx,by,bz,null))return;
   if(setBlockWorld(bx,by,bz,item.type.replace('slab','double_slab')))consumeSelected();
   return;
  }
 }
 if(!canPlaceAt(bx,by,bz)||(getBlock(bx,by,bz)&&getBlock(bx,by,bz)!=='water'))return;
 if(item.type==='sugar_cane'){if(!caneOk(bx,by,bz)){showNotice('Sugar cane needs sand, dirt or grass right next to water.');return;}if(getBlock(bx,by-1,bz)!=='sugar_cane')caneKeys.add(key(bx,by,bz));}
 if(item.type.endsWith('_sapling')&&!(DIRT_TYPES.has(getBlock(bx,by-1,bz))||GRASS_TYPES.has(getBlock(bx,by-1,bz)))){showNotice('Saplings need grass or dirt beneath them.');return;}
 if(item.type==='bed'||item.type.startsWith('bed_')){placeBed(bx,by,bz,item.type==='bed'?0:DYE_NAMES.indexOf(item.type.slice(4))+1);return;}
 let specialMeta=null;
 if(item.type==='torch'){
  const lmT={'0,1':2,'0,-1':0,'1,0':3,'-1,0':1}[Math.round(normal.x)+','+Math.round(normal.z)];
  if(normal.y===0&&OPAQUE[ID[type]]&&lmT!==undefined)specialMeta=4|lmT;
  else if(normal.y>=0&&supportsDoor(bx,by-1,bz))specialMeta=0;
  else{showNotice('Torches go on the top or side of a solid block.');return;}
 }
 if(item.type==='lantern'){
  const below=supportsDoor(bx,by-1,bz),above=!!OPAQUE[getId(bx,by+1,bz)];
  if(normal.y<0&&above)specialMeta=4;else if(below)specialMeta=0;else if(above)specialMeta=4;
  else{showNotice('Lanterns sit on a block or hang from one.');return;}
 }

 if(item.type.startsWith('cushion')){
  const st=getBlock(bx,by-1,bz),okSup=!!st&&st!=='water'&&!st.startsWith('cushion')&&(!!OPAQUE[ID[st]]||!!SHP[st]);
  if(normal.y<=0||!okSup){showNotice('Cushions go on top of a block, slab or stair.');return;}
  // Clicking the lower step of a stair (or the top of a bottom slab) puts the cushion down at that lower height.
  specialMeta=(hit.point.y-(by-1))<.25?4:0;
 }
 const isDoor=!!DOOR_ITEMS[item.type],pt=isDoor?DOOR_ITEMS[item.type]:item.type,doorTop=pt.replace('door_bottom','door_top');
 const upside=normal.y<0||(normal.y===0&&hit.point.y-y>0);
 const sk=SHP[pt]?.[1];
 let meta=((isDoor||sk==='stairs'||pt==='chest'||pt==='sign')?facing():0)|((sk==='slab'||sk==='stairs')&&upside?4:0);
 // Trapdoors: bit 0-1 hinge side, bit 2 open, bit 3 upper half. Side clicks hinge against that wall.
 if(TRAP_TYPES.has(pt))meta=(normal.y===0?{'0,1':2,'0,-1':0,'1,0':3,'-1,0':1}[Math.round(normal.x)+','+Math.round(normal.z)]:facing())|(upside?8:0);
 if(specialMeta!==null)meta=specialMeta;
 if(isDoor){
  if(!canPlaceAt(bx,by+1,bz)||getBlock(bx,by+1,bz)){showNotice('A door needs two empty blocks of height.');return;}
  if(!supportsDoor(bx,by-1,bz)){showNotice('Place a door on a solid, flat surface.');return;}
  if(hitBoxes(player.x,player.feet,player.z,bx,by+1,bz,blockBoxes(doorTop,meta)))return;
 }
 if(pt!=='torch'&&!pt.startsWith('cushion')&&hitBoxes(player.x,player.feet,player.z,bx,by,bz,blockBoxes(pt,meta,bx,by,bz)))return;
 if(!addBlock(bx,by,bz,pt,meta))return;
 if(isDoor)addBlock(bx,by+1,bz,doorTop,meta);
 consumeSelected();
 if(pt==='sign')openSign(key(bx,by,bz));
}

/* ================= SURVIVAL / BEDS ================= */
function onLadder(){
 const x=Math.round(player.x),z=Math.round(player.z);
 return getBlock(x,Math.round(player.feet+.05),z)==='ladder'||getBlock(x,Math.round(player.feet+.9),z)==='ladder';
}
function isInWater(){return getBlock(Math.round(player.x),Math.round(player.feet+.3),Math.round(player.z))==='water';}
function updateVitals(){
 for(const [name,value,max] of [['health',survival.health,20],['hunger',survival.hunger,20],['stamina',survival.stamina,100]]){
  document.getElementById(name+'Fill').style.width=Math.max(0,value)/max*100+'%';
  document.getElementById(name+'Text').textContent=`${Math.ceil(value)} / ${max}`;
 }
 document.getElementById('xpFill').style.width=(survival.xp/100*100)+'%';
 document.getElementById('xpText').textContent=`${survival.xp} / 100`;
 document.getElementById('xpLevel').textContent=`Lv ${survival.xpLevel}`;
}
function gainXP(amount){
 if(gameMode==='creative'||survival.dead||amount<=0)return;
 survival.xp+=amount;playSound('orb',{vol:.5});
 while(survival.xp>=100){survival.xp-=100;survival.xpLevel++;}
 updateVitals();
}
function damagePlayer(amount,cause,ignoreArmor=false){
 if(gameMode==='creative'||survival.dead||sleepTimer>0||amount<=0)return;
 if(!ignoreArmor)amount=Math.max(1,Math.round(amount*(1-Math.min(.7,armorPoints()*.035))));
 survival.health=Math.max(0,survival.health-amount);survival.regen=0;playSound('hurt',{vol:.9});
 const flash=document.getElementById('damageFlash');flash.style.opacity='.65';
 clearTimeout(damagePlayer.timer);damagePlayer.timer=setTimeout(()=>flash.style.opacity=0,220);
 if(survival.health<=0){
  survival.dead=true;survival.sprinting=false;survival.xp=0;survival.xpLevel=0;pauseInput();returnItems();
  inventoryOpen=tableOpen=furnaceOpen=chestOpen=false;
  document.querySelectorAll('.panel').forEach(el=>el.style.display='none');
  if(pointerLocked)document.exitPointerLock();start.style.display='none';
  document.getElementById('deathReason').textContent='You died from '+cause+'.';
  document.getElementById('deathScreen').style.display='flex';
 }
 updateVitals();
}
function eatFood(){
 const it=hotbar[selected];if(!it||!FOOD[it.type]||survival.dead||survival.eatCooldown>0)return false;
 if(survival.hunger>=20){showNotice('You are not hungry.');return false;}
 survival.hunger=Math.min(20,survival.hunger+FOOD[it.type]);survival.eatCooldown=.6;
 playSound('nom',{vol:.8});showNotice('Ate '+itemName(it.type)+'.');consumeSelected();updateVitals();return true;
}
function tickSurvival(dt,moving,wet){
 if(gameMode==='creative'){survival.health=20;survival.hunger=20;survival.stamina=100;survival.sprinting=false;survival.fallPeak=player.feet;updateVitals();return;}
 survival.attackCooldown=Math.max(0,survival.attackCooldown-dt);survival.eatCooldown=Math.max(0,survival.eatCooldown-dt);
 if(survival.dead||sleepTimer>0)return;
 const sprint=survival.sprinting&&moving&&!wet;
 survival.stamina=Math.max(0,Math.min(100,survival.stamina+(sprint?-23:17)*dt));
 if(survival.stamina<=0)survival.exhausted=true;
 if(survival.stamina>=25)survival.exhausted=false;
 survival.hunger=Math.max(0,survival.hunger-dt*(sprint?.11:moving?.035:.012));
 if(survival.hunger<=0){survival.starve+=dt;if(survival.starve>=4){survival.starve=0;damagePlayer(1,'starvation',true);}}
 else survival.starve=0;
 if(survival.hunger>=18&&survival.health<20){survival.regen+=dt;if(survival.regen>=4){survival.regen=0;survival.health=Math.min(20,survival.health+1);survival.hunger=Math.max(0,survival.hunger-.5);}}
 else survival.regen=0;
 if(wet)survival.fallPeak=player.feet;else survival.fallPeak=Math.max(survival.fallPeak,player.feet);
 if(player.feet<MIN_Y-8)damagePlayer(20,'falling into the void',true);
 updateVitals();
}
function bedDirection(f){return [[0,-1],[-1,0],[0,1],[1,0]][f&3];}
function placeBed(x,y,z,ci=0){
 const f=facing(),[dx,dz]=bedDirection(f),hx=x+dx,hz=z+dz;
 if(!canPlaceAt(hx,y,hz)||getBlock(hx,y,hz)||getBlock(x,y,z)||!supportsDoor(x,y-1,z)||!supportsDoor(hx,y-1,hz)){
  showNotice('A bed needs two empty blocks on a solid floor.');return false;
 }
 if(hitBoxes(player.x,player.feet,player.z,x,y,z,blockBoxes('bed_foot',f))||hitBoxes(player.x,player.feet,player.z,hx,y,hz,blockBoxes('bed_head',f)))return false;
 if(!addBlock(x,y,z,'bed_foot',f|(ci<<4)))return false;
 addBlock(hx,y,hz,'bed_head',f|(ci<<4));consumeSelected();return true;
}
function validBed(b){
 if(!b)return false;const [dx,dz]=bedDirection(b.f);
 return getBlock(b.x,b.y,b.z)==='bed_foot'&&getBlock(b.x+dx,b.y,b.z+dz)==='bed_head';
}
function useBed(x,y,z){
 const f=getMeta(x,y,z),[dx,dz]=bedDirection(f);
 const b=getBlock(x,y,z)==='bed_head'?{x:x-dx,y,z:z-dz,f}:{x,y,z,f};
 if(!validBed(b)){showNotice('This bed is incomplete.');return;}
 bedSpawn=b;
 if(!isNight()){showNotice('Respawn point set! You can sleep here at night.');return;}
 sleepTimer=2;pauseInput();document.getElementById('sleepShade').style.opacity='1';
 showNotice('Respawn point set. Sleeping until morning…');
}
function ensureChunkAt(x,z){
 const cx=Math.floor(x/CS),cz=Math.floor(z/CS),k=ck(cx,cz);
 if(!chunks.has(k)){const ch=genChunk(cx,cz);chunks.set(k,ch);buildChunk(ch);}
}
function groundAt(x,z){
 const bx=Math.round(x),bz=Math.round(z);if(!canPlaceAt(bx,0,bz))return null;
 for(let y=MIN_Y+HT-1;y>=MIN_Y;y--){
  const type=getBlock(bx,y,bz);if(!type||type==='water'||type==='torch'||type==='wheat_crop'||type==='tall_grass'||type==='sugar_cane')continue;
  const boxes=blockBoxes(type,getMeta(bx,y,bz),bx,y,bz);
  return {feet:y+(boxes?Math.max(...boxes.map(b=>b[4])):.5),type,y};
 }
 return null;
}
function safeSpawnNear(x,z,range=4){
 for(let radius=0;radius<=range;radius++)for(let dx=-radius;dx<=radius;dx++)for(let dz=-radius;dz<=radius;dz++){
  if(Math.max(Math.abs(dx),Math.abs(dz))!==radius)continue;
  const px=Math.round(x)+dx,pz=Math.round(z)+dz;ensureChunkAt(px,pz);
  const ground=groundAt(px,pz);if(!ground||['leaves','log','fence'].includes(ground.type))continue;
  if(getBlock(px,Math.round(ground.feet+.6),pz)==='water')continue;
  const feet=ground.feet+.01;if(!collides(px,feet,pz))return {x:px,z:pz,feet};
 }
 return null;
}
function respawnPlayer(){
 let position=null;
 if(bedSpawn){ensureChunkAt(bedSpawn.x,bedSpawn.z);const [dx,dz]=bedDirection(bedSpawn.f);ensureChunkAt(bedSpawn.x+dx,bedSpawn.z+dz);
  if(validBed(bedSpawn))position=safeSpawnNear(bedSpawn.x,bedSpawn.z,3);
 }
 if(!position){position=safeSpawnNear(worldSpawn.x,worldSpawn.z,8);if(bedSpawn)showNotice('Your bed is missing or obstructed. Returned to world spawn.');}
 if(!position){showNotice('Spawn is obstructed. Clear space and try again.');return false;}
 Object.assign(player,position,{vy:0,grounded:false});Object.assign(survival,{health:20,hunger:20,stamina:100,xp:0,xpLevel:0,dead:false,exhausted:false,sprinting:false,starve:0,regen:0,fallPeak:player.feet});
 pauseInput();camera.position.set(player.x,player.feet+EYE_HEIGHT,player.z);
 document.getElementById('deathScreen').style.display='none';start.style.display='flex';updateVitals();return true;
}
document.getElementById('respawnButton').addEventListener('click',respawnPlayer);

/* ================= MOB SKINS ================= */
// Pixel-art face/body textures and pivoted limbs, so mobs read as proper characters instead of flat coloured boxes.
const mobTexCache=new Map(),mobMatCache=new Map(),mobGeoCache=new Map();
const mpx=(g,x,y,w,h,c)=>{g.fillStyle=c;g.fillRect(x,y,w,h);};
function mobTex(id,w,h,draw){
 let t=mobTexCache.get(id);if(t)return t;
 const c=document.createElement('canvas');c.width=w;c.height=h;draw(c.getContext('2d'),w,h);
 t=new THREE.CanvasTexture(c);t.magFilter=t.minFilter=THREE.NearestFilter;t.colorSpace=THREE.SRGBColorSpace;
 mobTexCache.set(id,t);return t;
}
function mobMat(id,w,h,draw,opts){
 let m=mobMatCache.get(id);if(m)return m;
 m=new THREE.MeshLambertMaterial(Object.assign({map:mobTex(id,w,h,draw)},opts||{}));mobMatCache.set(id,m);return m;
}
function mobSpeckle(g,w,h,cols,n,seed){const r=mulberry(seed);for(let i=0;i<n;i++)mpx(g,Math.floor(r()*w),Math.floor(r()*h),1,1,cols[Math.floor(r()*cols.length)]);}
const mobSkin=(id,base,cols,n,seed)=>mobMat(id,16,16,g=>{mpx(g,0,0,16,16,base);mobSpeckle(g,16,16,cols,n,seed);});
function mobGeo(w,h,d){const k=w+'|'+h+'|'+d;let g=mobGeoCache.get(k);if(!g)mobGeoCache.set(k,g=new THREE.BoxGeometry(w,h,d));return g;}
function mobPart(parent,w,h,d,x,y,z,mats){const m=new THREE.Mesh(mobGeo(w,h,d),mats);m.position.set(x,y,z);parent.add(m);return m;}
// A limb pivots from its top (hip / shoulder), so walking swings it instead of spinning it about its middle.
function mobLimb(parent,w,h,d,x,hipY,z,mats){const p=new THREE.Group();p.position.set(x,hipY,z);parent.add(p);const m=new THREE.Mesh(mobGeo(w,h,d),mats);m.position.y=-h/2;p.add(m);return p;}
// BoxGeometry face order: +x, -x, +y, -y, +z (back), -z (front: mobs face -z)
const mobFaces=(side,top,bottom,front,back)=>[side,side,top,bottom,back||side,front||side];
// Diagonal pairs move together (front-left + back-right), matching the j%2 walk cycle.
const quadLegs=(group,legs,x,z,hip,w,mat)=>{for(const [sx,sz] of [[-1,-1],[1,-1],[1,1],[-1,1]])legs.push(mobLimb(group,w,hip,w,sx*x,hip,sz*z,mat));};
const hexOf=n=>'#'+n.toString(16).padStart(6,'0');

function buildAnimalModel(kind,group,legs){
 if(kind==='pig'){
  const skin=mobSkin('pig_skin','#e8a3a8',['#df959b','#f0b2b6','#e29ea3','#ea9aa1'],70,11);
  const face=mobMat('pig_face',8,8,g=>{mpx(g,0,0,8,8,'#e8a3a8');mobSpeckle(g,8,8,['#df959b','#f0b2b6'],12,5);
   mpx(g,1,2,1,1,'#ffffff');mpx(g,2,2,1,1,'#2a2438');mpx(g,5,2,1,1,'#2a2438');mpx(g,6,2,1,1,'#ffffff');});
  const snout=mobMat('pig_snout',6,4,g=>{mpx(g,0,0,6,4,'#f3b6bb');mpx(g,1,1,1,2,'#8a4b55');mpx(g,4,1,1,2,'#8a4b55');mpx(g,0,3,6,1,'#e09aa2');});
  const snoutSide=mobSkin('pig_snout_side','#eeaab0',['#e09aa2','#f3b6bb'],6,3);
  const ear=mobSkin('pig_ear','#d98a93',['#c97b84'],3,8);
  const leg=mobMat('pig_leg',4,8,g=>{mpx(g,0,0,4,8,'#e29ea3');mobSpeckle(g,4,8,['#d98f96','#eaa8ad'],6,9);mpx(g,0,6,4,2,'#8c565c');});
  mobPart(group,.7,.62,1.0,0,.76,0,skin);
  mobPart(group,.5,.5,.5,0,.9,-.66,mobFaces(skin,skin,skin,face));
  mobPart(group,.26,.18,.12,0,.84,-.97,mobFaces(snoutSide,snoutSide,snoutSide,snout));
  for(const sx of [-.17,.17])mobPart(group,.13,.13,.04,sx,1.19,-.6,ear);
  mobPart(group,.06,.06,.1,0,.96,.55,skin);
  quadLegs(group,legs,.22,.33,.45,.2,leg);
 }else if(kind==='cow'){
  const hide=mobMat('cow_hide',16,16,g=>{mpx(g,0,0,16,16,'#4e3a2b');mobSpeckle(g,16,16,['#5b4432','#45331f','#3f2e22'],46,21);
   for(const [x,y,w,h] of [[2,3,5,4],[9,8,5,5],[1,11,4,3],[11,1,4,3],[6,0,3,2]])mpx(g,x,y,w,h,'#ece5d6');});
  const face=mobMat('cow_face',8,8,g=>{mpx(g,0,0,8,8,'#4e3a2b');mobSpeckle(g,8,8,['#5b4432','#45331f'],10,22);
   mpx(g,3,0,2,8,'#eee6d6');mpx(g,1,3,1,1,'#ffffff');mpx(g,2,3,1,1,'#1b1b1b');mpx(g,5,3,1,1,'#1b1b1b');mpx(g,6,3,1,1,'#ffffff');});
  const muzzle=mobMat('cow_muzzle',6,4,g=>{mpx(g,0,0,6,4,'#d9b8a6');mpx(g,1,1,1,2,'#6b4a3f');mpx(g,4,1,1,2,'#6b4a3f');});
  const muzzleSide=mobSkin('cow_muzzle_side','#cfa995',['#bf9784'],5,23);
  const horn=mobSkin('cow_horn','#e8e0c8',['#d4ccb2'],3,24),ear=mobSkin('cow_ear','#4e3a2b',['#3f2e22'],4,25),udder=mobSkin('cow_udder','#e8a1a8',['#d98f96'],5,26);
  const leg=mobMat('cow_leg',4,8,g=>{mpx(g,0,0,4,8,'#4e3a2b');mobSpeckle(g,4,8,['#5b4432','#45331f'],7,27);mpx(g,0,6,4,2,'#2b2018');});
  mobPart(group,.76,.66,1.05,0,.8,0,hide);
  mobPart(group,.5,.5,.5,0,.96,-.7,mobFaces(hide,hide,hide,face));
  mobPart(group,.3,.2,.1,0,.88,-.99,mobFaces(muzzleSide,muzzleSide,muzzleSide,muzzle));
  for(const sx of [-1,1]){mobPart(group,.06,.16,.06,sx*.26,1.28,-.64,horn);mobPart(group,.14,.07,.2,sx*.33,1.12,-.62,ear);}
  mobPart(group,.22,.1,.26,0,.42,.3,udder);
  quadLegs(group,legs,.24,.36,.47,.2,leg);
 }else{ // sheep
  const fleece=mobMat('sheep_fleece',16,16,g=>{mpx(g,0,0,16,16,'#efece0');mobSpeckle(g,16,16,['#dcd8c8','#f8f6ee','#e4e0d2','#d2cebd'],100,61);});
  const face=mobMat('sheep_face',8,8,g=>{mpx(g,0,0,8,8,'#a8977f');mobSpeckle(g,8,8,['#9b8a73','#b3a28a'],10,62);
   mpx(g,1,3,1,1,'#ffffff');mpx(g,2,3,1,1,'#2b2220');mpx(g,5,3,1,1,'#2b2220');mpx(g,6,3,1,1,'#ffffff');mpx(g,3,5,2,1,'#5a4a40');});
  const tan=mobSkin('sheep_tan','#a8977f',['#9b8a73','#b3a28a'],10,63);
  const leg=mobMat('sheep_leg',4,8,g=>{mpx(g,0,0,4,8,'#a8977f');mobSpeckle(g,4,8,['#9b8a73'],5,64);mpx(g,0,6,4,2,'#3a302a');});
  mobPart(group,.84,.7,1.02,0,.87,0,fleece);
  mobPart(group,.5,.46,.34,0,1.0,-.45,fleece);
  mobPart(group,.36,.38,.4,0,.98,-.72,mobFaces(tan,tan,tan,face));
  mobPart(group,.4,.1,.4,0,1.2,-.7,fleece);
  for(const sx of [-.25,.25])mobPart(group,.14,.07,.12,sx,1.02,-.68,tan);
  quadLegs(group,legs,.22,.32,.52,.16,leg);
 }
}

