  mpx(g,1,2,2,1,'#2b3b2c');mpx(g,5,2,2,1,'#2b3b2c');mpx(g,1,3,2,1,'#0f1a14');mpx(g,5,3,2,1,'#0f1a14');mpx(g,1,3,1,1,'#b8e665');mpx(g,6,3,1,1,'#b8e665');
