const villagers=[];
const villagerMats={
 skin:new THREE.MeshLambertMaterial({color:0xb98968}),nose:new THREE.MeshLambertMaterial({color:0xa97858}),
 pants:new THREE.MeshLambertMaterial({color:0x3d342c}),eyes:new THREE.MeshBasicMaterial({color:0x24211d})
};
const profMats={};
function profMat(p){return profMats[p]||(profMats[p]={robe:new THREE.MeshLambertMaterial({color:PROF[p].robe}),trim:new THREE.MeshLambertMaterial({color:PROF[p].trim})});}
function groundNear(x,z,feet){
 const bx=Math.round(x),bz=Math.round(z);if(!canPlaceAt(bx,0,bz))return null;
 for(let y=Math.floor(feet)+2;y>=MIN_Y;y--){
  const type=getBlock(bx,y,bz);if(!type||['water','torch','wheat_crop','tall_grass','sugar_cane'].includes(type))continue;
  const boxes=blockBoxes(type,getMeta(bx,y,bz),bx,y,bz);
  return {feet:y+(boxes?Math.max(...boxes.map(b=>b[4])):.5),type,y};
 }
 return null;
}
function spawnVillager(v,job){
 const x=v.cx+job.x,z=v.cz+job.z,ground=groundNear(x,z,v.base);
 if(!ground||['water','leaves','log','fence','wheat_crop'].includes(ground.type)||collides(x,ground.feet+.01,z))return null;
 const group=new THREE.Group(),legs=[],pm=profMat(job.prof);
 buildVillagerModel(group,legs,job.prof);
 group.position.set(x,ground.feet,z);scene.add(group);
 const person={kind:'villager',prof:job.prof,group,legs,x,z,feet:ground.feet,dir:Math.random()*Math.PI*2,think:1+Math.random()*3,walk:true,phase:0,home:v,anchor:{x,z},villageKey:v.a+','+v.b,uses:{},day:dayNumber};
 villagers.push(person);return person;
}
let villagerSpawnTimer=1;
function tickVillagers(dt){
 villagerSpawnTimer-=dt;
 const here=villageAt(player.x,player.z);
 if(villagerSpawnTimer<=0&&here){
  villagerSpawnTimer=3;
  const vk=here.v.a+','+here.v.b,job=villagePlan(here.v).jobs.find(j=>!villagers.some(o=>o.villageKey===vk&&o.prof===j.prof));
  if(job)spawnVillager(here.v,job);
 }
 for(let i=villagers.length-1;i>=0;i--){
  const v=villagers[i];
  if(Math.hypot(v.x-player.x,v.z-player.z)>85){scene.remove(v.group);villagers.splice(i,1);continue;}
  if(chestOpen&&tradeVillager===v){v.walk=false;v.think=1;v.dir=Math.atan2(player.x-v.x,player.z-v.z);}
  else{
   v.think-=dt;
   if(v.think<=0){v.dir=Math.random()*Math.PI*2;v.walk=Math.random()>.25;v.think=2+Math.random()*4;}
  }
  if(v.walk){
   const nx=v.x+Math.sin(v.dir)*dt*.55,nz=v.z+Math.cos(v.dir)*dt*.55,g=groundNear(nx,nz,v.feet);
   if(g&&Math.hypot(nx-v.anchor.x,nz-v.anchor.z)<5&&Math.abs(g.feet-v.feet)<=.65&&getBlock(Math.round(nx),Math.round(g.feet+.6),Math.round(nz))!=='water'&&!collides(nx,g.feet+.01,nz)){
    v.x=nx;v.z=nz;v.feet=g.feet;v.phase+=dt*.55*7;
   }else{v.dir=Math.atan2(v.anchor.x-v.x,v.anchor.z-v.z)+(Math.random()-.5);v.think=.7;}
  }
  const under=groundNear(v.x,v.z,v.feet);if(under&&under.feet<v.feet)v.feet=Math.max(under.feet,v.feet-6*dt);
  v.group.position.set(v.x,v.feet,v.z);v.group.rotation.y=v.dir+Math.PI;
  v.hm=(v.hm??3+Math.random()*10)-dt;if(v.hm<=0){v.hm=12+Math.random()*14;playSoundAt('villager',v.x,v.z,{vol:.7});}
  v.legs.forEach((leg,j)=>leg.rotation.x=v.walk?Math.sin(v.phase+(j%2)*Math.PI)*.32:0);
 }
}


