const fairies=[];
const fairyMaterials={
 skin:new THREE.MeshLambertMaterial({color:0xffd5e9,emissive:0x4d1e57,emissiveIntensity:.28}),
 hair:new THREE.MeshLambertMaterial({color:0x8b54b4}),
 dress:new THREE.MeshLambertMaterial({color:0xe7a8d8}),
 dressAlt:new THREE.MeshLambertMaterial({color:0xbba0ed}),
 wing:new THREE.MeshLambertMaterial({color:0xffb9ee,transparent:true,opacity:.68,side:THREE.DoubleSide,emissive:0x8c3e9d,emissiveIntensity:.55,depthWrite:false}),
 eye:new THREE.MeshBasicMaterial({color:0x4a245a})
};
const fairyBox=new THREE.BoxGeometry(1,1,1),fairyWingGeo=new THREE.PlaneGeometry(.43,.65);
let fairySpawnTimer=1.5;
function spawnFairy(x,z,index=0){
 const ground=groundNear(x,z,player.feet)||groundAt(x,z);if(!ground)return null;
 const group=new THREE.Group();
 buildFairyBody(group);
 const wl=new THREE.Mesh(fairyWingGeo,fairyMaterials.wing),wr=new THREE.Mesh(fairyWingGeo,fairyMaterials.wing);
 wl.position.set(-.22,.14,.10);wr.position.set(.22,.14,.10);wl.rotation.z=.32;wr.rotation.z=-.32;group.add(wl,wr);
 const glow=new THREE.PointLight(index%2?0xc98eff:0xffa8dc,.7,5,2);glow.position.y=.3;group.add(glow);
 group.position.set(x,ground.feet+1.8,z);scene.add(group);
 const fairy={group,x,z,feet:ground.feet+1.8,homeX:x,homeZ:z,targetX:x,targetZ:z,think:Math.random()*2+1,phase:Math.random()*6,wingL:wl,wingR:wr,glow,targetDrop:null};
 fairies.push(fairy);return fairy;
}
function releaseFairyDrop(fairy){if(fairy.targetDrop&&fairy.targetDrop.claimedBy===fairy)fairy.targetDrop.claimedBy=null;fairy.targetDrop=null;}
function tickFairies(dt){
 const inFairyGrove=biomeAt(player.x,player.z)==='fairy_forest';
 fairySpawnTimer-=dt;
 if(inFairyGrove&&fairySpawnTimer<=0&&fairies.length<6){
  fairySpawnTimer=2.1;const a=Math.random()*Math.PI*2,r=5+Math.random()*12;
  spawnFairy(player.x+Math.cos(a)*r,player.z+Math.sin(a)*r,fairies.length);
 }else if(!inFairyGrove)fairySpawnTimer=Math.min(fairySpawnTimer,1.5);
 for(let i=fairies.length-1;i>=0;i--){
  const f=fairies[i];
  if(Math.hypot(f.x-player.x,f.z-player.z)>88){releaseFairyDrop(f);scene.remove(f.group);fairies.splice(i,1);continue;}
  if(!f.targetDrop||!droppedItems.includes(f.targetDrop)||f.targetDrop.item.type!=='rhinestone'){
   releaseFairyDrop(f);
   let nearest=null,dist=22;
   if(inFairyGrove)for(const d of droppedItems){if(d.item.type!=='rhinestone'||d.claimedBy)continue;const n=Math.hypot(d.sprite.position.x-f.x,d.sprite.position.z-f.z);if(n<dist){nearest=d;dist=n;}}
   if(nearest){f.targetDrop=nearest;nearest.claimedBy=f;}
  }
  let tx=f.targetX,tz=f.targetZ,ty=f.feet;
  if(f.targetDrop&&droppedItems.includes(f.targetDrop)){
   tx=f.targetDrop.sprite.position.x;tz=f.targetDrop.sprite.position.z;ty=f.targetDrop.sprite.position.y+.2;
  }else{
   f.think-=dt;if(f.think<=0){const a=Math.random()*Math.PI*2,r=2+Math.random()*5;f.targetX=f.homeX+Math.cos(a)*r;f.targetZ=f.homeZ+Math.sin(a)*r;f.think=2+Math.random()*3;}
  }
  const dx=tx-f.x,dz=tz-f.z,dist=Math.hypot(dx,dz);
  const speed=f.targetDrop?4.2:1.0;
  if(dist>.18){f.x+=dx/dist*Math.min(dist,speed*dt);f.z+=dz/dist*Math.min(dist,speed*dt);}
  f.phase+=dt*(f.targetDrop?5:2.2);
  const bob=Math.sin(f.phase)*.16;
  const targetFeet=f.targetDrop?ty:f.feet;
  f.group.position.set(f.x,targetFeet+bob,f.z);f.group.rotation.y=Math.atan2(dx,dz);
  f.wingL.rotation.y=Math.sin(f.phase*3)*.32;f.wingR.rotation.y=-Math.sin(f.phase*3)*.32;
  f.glow.intensity=.55+Math.sin(f.phase*2)*.2;
  if(f.targetDrop&&droppedItems.includes(f.targetDrop)&&Math.hypot(f.x-tx,f.z-tz)<.72&&Math.abs(f.group.position.y-ty)<2){
   const index=droppedItems.indexOf(f.targetDrop),drop=f.targetDrop;
   if(index>=0){droppedItems.splice(index,1);scene.remove(drop.sprite);drop.sprite.material.map?.dispose();drop.sprite.material.dispose();addItem('fairy_dust',20);gainXP(3);showNotice('A fairy traded your rhinestone for 20 Fairy Dust!');}
   releaseFairyDrop(f);f.think=.7;
  }
 }
}

function mobTarget(){
 camera.updateMatrixWorld();const d=new THREE.Vector3();camera.getWorldDirection(d);
 const ray=new THREE.Ray(camera.position,d),block=getTarget();let distance=block?camera.position.distanceTo(block.point):4,best=null;
 for(const a of [...animals,...zombies,...skeletons,...spiders]){
  const h=a.targetHeight??(a.hostile?1.95:1.25),w=a.targetWidth??(a.hostile?.55:.5),depth=a.targetDepth??(a.hostile?.5:.6);
  const box=new THREE.Box3(new THREE.Vector3(a.x-w,a.feet,a.z-depth),new THREE.Vector3(a.x+w,a.feet+h,a.z+depth));
  const p=ray.intersectBox(box,new THREE.Vector3());if(p){const n=camera.position.distanceTo(p);if(n<distance&&n<4){distance=n;best=a;}}
 }
 return best;
}
const MELEE={sword:{wooden:4,stone:5,iron:6,diamond:7,rhinestone:8},axe:{wooden:3,stone:4,iron:5,diamond:6,rhinestone:7}};
function attackMob(){
 const pt=mpPlayerTarget(),a=mobTarget();
 if(!a&&!pt)return false;
 if(pt&&(!a||Math.hypot(a.x-camera.position.x,a.z-camera.position.z)>pt.dist)){
  if(survival.attackCooldown>0)return true;
  const it=hotbar[selected],tool=it&&ITEMS[it.type];
  survival.attackCooldown=tool?.tool==='sword'?.45:.6;
  let damage=1;if(tool?.tool==='sword'||tool?.tool==='axe')damage=MELEE[tool.tool][tool.tier]||2;else if(tool?.tool)damage=2;
  if(tool?.tool)damageHeldTool();
  mpSend({t:'hit',target:pt.r.id,dmg:damage});showNotice('Hit '+pt.r.name);
  return true;
 }
 if(survival.attackCooldown>0)return true;
 const it=hotbar[selected],tool=it&&ITEMS[it.type];
 survival.attackCooldown=tool?.tool==='sword'?.45:.6;
 let damage=1;
 if(tool?.tool==='sword'||tool?.tool==='axe')damage=MELEE[tool.tool][tool.tier]||2;
 else if(tool?.tool)damage=2;
 if(tool?.tool)damageHeldTool();
 return hurtMob(a,damage);
}
function hurtMob(a,damage){
 if(!a.hostile)playAnimalSound(a,.9);
 playSound('hit',{vol:.8});if(a.kind==='zombie')playSoundAt('zombie',a.x,a.z,{vol:.7,rate:1.1});
 a.hp-=damage;a.hurt=.55;
 const away=Math.hypot(a.x-player.x,a.z-player.z)||1;
 a.kbx=(a.x-player.x)/away*5.2;a.kbz=(a.z-player.z)/away*5.2;
 if(a.hostile){
  a.dir=Math.atan2(player.x-a.x,player.z-a.z);
  if(a.hp<=0){
   scene.remove(a.group);
   const list=a.kind==='zombie'?zombies:a.kind==='skeleton'?skeletons:spiders,idx=list.indexOf(a);if(idx>=0)list.splice(idx,1);
   if(a.kind==='skeleton'){addItem('bone',1+Math.floor(Math.random()*2));if(Math.random()<.55)addItem('arrow',1+Math.floor(Math.random()*2));}
   else if(a.kind==='spider'){addItem('string',1+Math.floor(Math.random()*2));if(Math.random()<.25)addItem('spider_eye',1);}
   gainXP(a.kind==='zombie'?7:a.kind==='skeleton'?6:5);showNotice(cap(a.kind)+' defeated.');
  }else showNotice(cap(a.kind)+' — '+a.hp+' health');
 }else{
  a.walk=true;a.dir=Math.atan2(a.x-player.x,a.z-player.z);a.think=1.4;
  if(a.hp<=0){
   const spec=animalKinds[a.kind];addItem(spec.meat,1+Math.floor(Math.random()*3));if(a.kind==='sheep')addItem('wool',1);if(a.kind==='cow')addItem('leather',1+Math.floor(Math.random()*2));
   scene.remove(a.group);animals.splice(animals.indexOf(a),1);gainXP(2);showNotice(cap(a.kind)+' dropped meat'+(a.kind==='sheep'?' and wool.':a.kind==='cow'?' and leather.':'.'));
  }else showNotice(cap(a.kind)+' — '+a.hp+' health');
 }
 return true;
}

let cropTimer=0;
function tickCrops(dt){
 cropTimer-=dt;if(cropTimer>0)return;cropTimer=3;
 for(const k of [...cropKeys]){
  const [x,y,z]=k.split(',').map(Number);
  if(!canPlaceAt(x,y,z))continue;
  if(getBlock(x,y,z)!=='wheat_crop'){cropKeys.delete(k);continue;}
  const meta=getMeta(x,y,z);if(meta>=3)continue;
  if(getBlock(x,y-1,z)!=='farmland')continue;
  if(Math.random()<.32)setBlockWorld(x,y,z,'wheat_crop',meta+1);
 }
}

let saplingTimer=0;
function growPlantedTree(x,y,z,species){
 const logType=species==='oak'?'log':species+'_log',leafType=species==='oak'?'leaves':species+'_leaves';
 const height=(species==='spruce'?6:species==='birch'?5:4)+Math.floor(hash2(x,z,worldSeed+501)*3);
 const cells=[];
 for(let dy=0;dy<height;dy++)cells.push([x,y+dy,z,logType]);
 if(species==='spruce'){
  for(let layer=0;layer<5;layer++){
   const yy=y+height-3+layer,radius=layer===0?1:layer===1?2:layer===2?3:layer===3?2:1;
   for(let dx=-radius;dx<=radius;dx++)for(let dz=-radius;dz<=radius;dz++){
    if(Math.abs(dx)+Math.abs(dz)>radius*2+1||(dx===0&&dz===0&&yy<y+height))continue;
    cells.push([x+dx,yy,z+dz,leafType]);
   }
  }
  cells.push([x,y+height+2,z,leafType]);
 }else{
  for(let dy=height-1;dy<=height+2;dy++){
   const radius=dy===height+2?1:2;
   for(let dx=-radius;dx<=radius;dx++)for(let dz=-radius;dz<=radius;dz++){
    if(Math.abs(dx)+Math.abs(dz)>3&&dy>=height)continue;
    if(dx===0&&dz===0&&dy<height)continue;
    cells.push([x+dx,y+dy,z+dz,leafType]);
   }
  }
  cells.push([x,y+height+3,z,leafType]);
 }
 // Refuse to grow through buildings, but allow leaves to fill their canopy around air.
 for(const [bx,by,bz,t] of cells){
  if(!canPlaceAt(bx,by,bz))return false;
  const existing=getBlock(bx,by,bz);
  if(existing&&!(bx===x&&bz===z&&by===y&&existing===species+'_sapling')&&existing!=='water'){
   if(t===leafType)continue;
   return false;
  }
 }
 saplingKeys.delete(key(x,y,z));
 for(const [bx,by,bz,t] of cells){
  if(getBlock(bx,by,bz)==='water'||!getBlock(bx,by,bz)||(bx===x&&by===y&&bz===z&&getBlock(bx,by,bz)===species+'_sapling'))setBlockWorld(bx,by,bz,t,0,true);
 }
 return true;
}
function tickSaplings(dt){
 saplingTimer-=dt;if(saplingTimer>0)return;saplingTimer=6;
 for(const k of [...saplingKeys]){
  const [x,y,z]=k.split(',').map(Number);
  if(!canPlaceAt(x,y,z))continue;
  const type=getBlock(x,y,z);
  if(!type||!type.endsWith('_sapling')){saplingKeys.delete(k);continue;}
  const ground=getBlock(x,y-1,z);if(!(DIRT_TYPES.has(ground)||GRASS_TYPES.has(ground)))continue;
  if(Math.random()<.16){const species=type==='oak_sapling'?'oak':type==='birch_sapling'?'birch':'spruce';if(growPlantedTree(x,y,z,species))showNotice(cap(species)+' tree grew.');}
 }
}

