const skyUniforms={uTop:{value:new THREE.Color(0x426f9b)},uHorizon:{value:new THREE.Color(0xffd1a0)},uBottom:{value:new THREE.Color(0x526b7c)},uSunDir:{value:new THREE.Vector3(0,1,0)},uDusk:{value:0}};
const skyDome=new THREE.Mesh(new THREE.SphereGeometry(620,40,24),new THREE.ShaderMaterial({
 uniforms:skyUniforms,side:THREE.BackSide,depthWrite:false,depthTest:false,fog:false,
 vertexShader:'varying vec3 vDir; void main(){vDir=normalize(position);gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',
 fragmentShader:'varying vec3 vDir;uniform vec3 uTop;uniform vec3 uHorizon;uniform vec3 uBottom;uniform vec3 uSunDir;uniform float uDusk;void main(){float h=clamp(vDir.y*.5+.5,0.0,1.0);vec3 sky=mix(uHorizon,uTop,pow(h,.82));sky=mix(uBottom,sky,smoothstep(-.42,-.02,vDir.y));float a=max(dot(normalize(vDir),normalize(uSunDir)),0.0);float glow=pow(a,18.0)*.9+pow(a,3.0)*.2;sky+=vec3(1.0,.48,.22)*glow*(.45+uDusk*.9);float haze=pow(max(0.0,1.0-abs(vDir.y)*4.0),2.0);sky=mix(sky,vec3(1.0,.55,.37),haze*uDusk*.22);gl_FragColor=vec4(sky,1.0);}'
}));skyDome.renderOrder=-100;scene.add(skyDome);
const glowCanvas=document.createElement('canvas');glowCanvas.width=glowCanvas.height=128;const glowCtx=glowCanvas.getContext('2d');
const glowGrad=glowCtx.createRadialGradient(64,64,2,64,64,64);glowGrad.addColorStop(0,'rgba(255,255,245,1)');glowGrad.addColorStop(.16,'rgba(255,224,180,.8)');glowGrad.addColorStop(.45,'rgba(255,164,105,.26)');glowGrad.addColorStop(1,'rgba(255,145,95,0)');glowCtx.fillStyle=glowGrad;glowCtx.fillRect(0,0,128,128);
const sunGlowTexture=new THREE.CanvasTexture(glowCanvas);sunGlowTexture.colorSpace=THREE.SRGBColorSpace;
const sunGlow=new THREE.Mesh(new THREE.PlaneGeometry(150,150),new THREE.MeshBasicMaterial({map:sunGlowTexture,transparent:true,opacity:.9,depthWrite:false,depthTest:false,fog:false,blending:THREE.AdditiveBlending}));sunGlow.renderOrder=-1;scene.add(sunGlow);

const starPositions=[];for(let i=0;i<180;i++){const a=hash2(i,1,90)*Math.PI*2,h=hash2(i,2,91)*.9+.1,r=Math.sqrt(1-h*h);starPositions.push(Math.cos(a)*r*450,h*450,Math.sin(a)*r*450);}
const starGeo=new THREE.BufferGeometry();starGeo.setAttribute('position',new THREE.Float32BufferAttribute(starPositions,3));
const stars=new THREE.Points(starGeo,new THREE.PointsMaterial({color:0xffffff,size:1.5,fog:false,depthWrite:false}));stars.renderOrder=-4;scene.add(stars);
const skyDay=new THREE.Color(0x87ceeb),skyNight=new THREE.Color(0x080e22),skyDusk=new THREE.Color(0xac6c65);
let daylight=1;
function isNight(){return dayTime>=.5;}
function tickDay(dt){
 if(survival.dead)return;
 if(sleepTimer>0){
  sleepTimer=Math.max(0,sleepTimer-dt);
  if(sleepTimer===0){dayTime=.04;dayNumber++;survival.stamina=100;survival.hunger=Math.max(0,survival.hunger-1);survival.fallPeak=player.feet;document.getElementById('sleepShade').style.opacity='0';showNotice('Good morning!');if(mp&&mp.joined)mpSend({t:'slept'});}
 }else{dayTime+=dt/DAY_SECONDS;if(dayTime>=1){dayTime%=1;dayNumber++;}}
 const angle=dayTime*Math.PI*2,elevation=Math.sin(angle);
 daylight=THREE.MathUtils.smoothstep(elevation,-.16,.22);
 sunDir.set(-Math.cos(angle)*.8,elevation,-.6).normalize();sun.position.copy(sunDir).multiplyScalar(60);
 const dusk=1-THREE.MathUtils.smoothstep(Math.abs(elevation),.025,.34);
 sun.intensity=.08+daylight*1.22+dusk*.55;sun.color.setHex(dusk>.12?0xffc38e:0xffffff);ambient.intensity=.2+daylight*1.65;
 ambient.color.setHex(daylight<.3?0x8698cf:0xffffff);ambient.groundColor.setHex(daylight<.3?0x22263d:0x777777);
 scene.background.copy(skyNight).lerp(skyDay,daylight);
 if(dusk>.01)scene.background.lerp(skyDusk,dusk*.42);
 skyUniforms.uTop.value.setHex(0x071226).lerp(new THREE.Color(0x4c93c6),daylight).lerp(new THREE.Color(0x523268),dusk*.9);
 skyUniforms.uHorizon.value.setHex(0x1b304c).lerp(new THREE.Color(0xc5eaff),daylight).lerp(new THREE.Color(0xffb16d),dusk);
 skyUniforms.uBottom.value.setHex(0x111b31).lerp(new THREE.Color(0x6e9fb5),daylight).lerp(new THREE.Color(0x9d6b75),dusk*.7);
 skyUniforms.uSunDir.value.copy(sunDir);skyUniforms.uDusk.value=dusk;
 scene.fog.color.copy(scene.background);sunHalo.material.color.copy(scene.background).lerp(new THREE.Color(0xffd095),.22);
 sunMesh.visible=sunHalo.visible=elevation>-.12;moonMesh.visible=elevation<.12;stars.visible=daylight<.35;
 const hour=Math.floor((dayTime*24+6)%24),minute=Math.floor(dayTime*24*60)%60;
 document.getElementById('timeHud').textContent=`Day ${dayNumber} · ${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')} · ${isNight()?'Night':'Day'} · ${BIOME_LABELS[biomeAt(player.x,player.z)]||'Plains'}`;
}
const CLOUD_CELL=12,CLOUD_N=18,CLOUD_Y=48;
const cloudMesh=new THREE.InstancedMesh(new THREE.BoxGeometry(CLOUD_CELL,3,CLOUD_CELL),
 new THREE.MeshLambertMaterial({color:0xffffff,fog:false}),(2*CLOUD_N+1)**2);
cloudMesh.frustumCulled=false;scene.add(cloudMesh);
let cloudKey='',cloudDrift=0;
const cloudDummy=new THREE.Object3D();
function updateSky(dt){
 cloudDrift+=dt*.45/CLOUD_CELL;
 skyDome.position.copy(camera.position);
 sunMesh.position.copy(camera.position).addScaledVector(sunDir,400);sunMesh.lookAt(camera.position);
 sunGlow.position.copy(camera.position).addScaledVector(sunDir,397);sunGlow.lookAt(camera.position);sunGlow.visible=sunMesh.visible;
 sunHalo.position.copy(camera.position).addScaledVector(sunDir,401);sunHalo.lookAt(camera.position);
 moonMesh.position.copy(camera.position).addScaledVector(sunDir,-400);moonMesh.lookAt(camera.position);stars.position.copy(camera.position);
 const drift=cloudDrift,di=Math.floor(drift);
 const pi=Math.round(camera.position.x/CLOUD_CELL),pj=Math.round(camera.position.z/CLOUD_CELL);
 cloudMesh.position.x=(drift-di)*CLOUD_CELL;
 const k=di+','+pi+','+pj;
 if(k===cloudKey)return;
 cloudKey=k;let n=0;
 for(let a=-CLOUD_N;a<=CLOUD_N;a++)for(let b=-CLOUD_N;b<=CLOUD_N;b++){
  if(vnoise((pi+a-di)*.32+100,(pj+b)*.32+100)<.57)continue;
  cloudDummy.position.set((pi+a)*CLOUD_CELL,CLOUD_Y,(pj+b)*CLOUD_CELL);
  cloudDummy.updateMatrix();cloudMesh.setMatrixAt(n++,cloudDummy.matrix);
 }
 cloudMesh.count=n;cloudMesh.instanceMatrix.needsUpdate=true;
}

/* ================= MENUS / SAVE ================= */
const WORLDS_KEY='mc-classic-worlds-v1';
const menuEl=document.getElementById('mainMenu'),menuSubtitle=document.getElementById('menuSubtitle');
const menuActions=document.getElementById('menuActions'),worldListEl=document.getElementById('worldList');
const createWorldForm=document.getElementById('createWorldForm'),menuStatus=document.getElementById('menuStatus');
const newWorldName=document.getElementById('newWorldName'),newWorldSeed=document.getElementById('newWorldSeed');
function setMenuStatus(text){menuStatus.textContent=text||''}
function refreshModeUI(){
 document.body.classList.toggle('creative-mode',gameMode==='creative');
 if(touchJump)touchJump.textContent=gameMode==='creative'?'Fly / Jump':'Jump';
 if(touchDown)touchDown.textContent=gameMode==='creative'?'Descend':'Sprint';
 const label=document.getElementById('timeHud');if(label&&started&&!menuOpen){label.dataset.mode=gameMode==='creative'?'Creative':'Survival';}
}
function worldMetas(){try{const v=JSON.parse(localStorage.getItem(WORLDS_KEY)||'[]');return Array.isArray(v)?v:[]}catch{return[]}}
function writeWorldMetas(list){try{localStorage.setItem(WORLDS_KEY,JSON.stringify(list))}catch{}}
function saveWorldData(id,data){localStorage.setItem('mc-classic-world-'+id,JSON.stringify(data))}
function readWorldData(id){try{return JSON.parse(localStorage.getItem('mc-classic-world-'+id)||'null')}catch{return null}}
function newWorldId(){return Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function seedFromInput(raw){
 const text=String(raw??'').trim();
 if(!text){const n=Math.floor(Math.random()*2147483647);return{num:n,label:String(n)}}
 if(/^-?\d+$/.test(text))return{num:Number(text)|0,label:text};
 let h=0;for(const ch of text)h=Math.imul(h,31)+ch.charCodeAt(0)|0;
 return{num:h|0,label:text};
}
function restoreArray(target,source,length){
 target.length=length;for(let i=0;i<length;i++)target[i]=(Array.isArray(source)&&source[i])?source[i]:null;
}
function resetWorldState(){
 for(const ch of chunks.values())clearMeshes(ch);
 chunks.clear();edits.clear();chests.clear();furnaces.clear();signs.clear();mapMarkers.length=0;mapTiles.clear();sitting=null;
 for(const list of [animals,zombies,skeletons,spiders,villagers,fairies])for(const a of list)scene.remove(a.group);
 for(const a of arrows)scene.remove(a.group);
 animals.length=0;zombies.length=0;skeletons.length=0;spiders.length=0;arrows.length=0;villagers.length=0;fairies.length=0;
 for(const d of droppedItems)scene.remove(d.sprite);
 droppedItems.length=0;clearLeafParticles();
 waterQueue.length=0;waterPending.clear();waterDirty.clear();waterSimActive=false;
 villageCache.clear();villagePlans.clear();villageChestKeys.clear();cropKeys.clear();caneKeys.clear();saplingKeys.clear();fairySpawnTimer=1.5;
 inventoryItems.fill(null);hotbar.fill(null);craftSlots.fill(null);tableCraftSlots.fill(null);armorSlots.fill(null);backSlot=null;fairyFlightTimer=0;
 cursorItem=null;selected=0;mining=false;target=null;outline.visible=false;
 Object.assign(survival,{health:20,hunger:20,stamina:100,xp:0,xpLevel:0,dead:false,exhausted:false,sprinting:false,starve:0,regen:0,fallPeak:0,attackCooldown:0,eatCooldown:0});
 Object.assign(player,{x:0,z:5,feet:20,vy:0,grounded:false});
 worldSpawn.x=0;worldSpawn.z=5;bedSpawn=null;sleepTimer=0;dayTime=.2;dayNumber=1;yaw=0;pitch=0;
 inventoryOpen=tableOpen=furnaceOpen=chestOpen=stonecutterOpen=false;tableStation='crafting';stonecutterSlot[0]=null;curFurnace=null;curChest=null;
 document.querySelectorAll('.panel').forEach(el=>el.style.display='none');
 document.getElementById('deathScreen').style.display='none';
 document.getElementById('sleepShade').style.opacity='0';
}
function starterItems(){} // new worlds start with an empty inventory
function seedSpawnChunks(x,z){
 for(let dx=-1;dx<=1;dx++)for(let dz=-1;dz<=1;dz++)ensureChunkAt(Math.round(x)+dx*CS,Math.round(z)+dz*CS);
}
function finishEnteringWorld(){
 started=true;inGame=true;menuOpen=false;
 if(gameMode!=='creative')creativeFlying=false;
 refreshModeUI();
 menuEl.classList.add('hidden');document.body.classList.remove('menu-open');
 waterSimActive=true;
 closeAllPanelsForMenu();
 updateHotbar();renderInventory();renderArmor();updateVitals();tickDay(0);updateSky(0);
 camera.position.set(player.x,player.feet+EYE_HEIGHT,player.z);
 updateStartOverlay();
}
function closeAllPanelsForMenu(){
 if(mapOpen){mapOpen=false;signOpen=false;mapPanel.style.display='none';}
 inventoryOpen=false;tableOpen=false;furnaceOpen=false;chestOpen=false;stonecutterOpen=false;tableStation='crafting';curFurnace=null;curChest=null;
 document.querySelectorAll('.panel').forEach(el=>el.style.display='none');
}
function createNewWorld(name,seedInput){
 mpDisconnect();
 const seed=seedFromInput(seedInput),now=Date.now(),id=newWorldId();
 const chosenMode=document.getElementById('newWorldMode').value||'survival';
 const chosenType=document.getElementById('newWorldType').value||'normal';
 gameMode=chosenMode;worldType=chosenType;creativeFlying=false;
 currentWorld={id,name:name||'New World',seedNum:seed.num,seedLabel:seed.label,gameMode,worldType,created:now,updated:now};
 worldSeed=seed.num;
 resetWorldState();
 starterItems();
 player.feet=20;
 seedSpawnChunks(0,5);
 const spawn=safeSpawnNear(0,5,14)||{x:0,z:5,feet:heightAt(0,5)+.51};
 worldSpawn.x=spawn.x;worldSpawn.z=spawn.z;
 Object.assign(player,spawn,{vy:0,grounded:false});
 updateChunks(true);
 waterSimActive=true;
 finishEnteringWorld();
 for(const kind of ['sheep','sheep','pig','cow']){
  let made=false;
  for(let radius=6;radius<=15&&!made;radius+=2)for(let i=0;i<12&&!made;i++){
   const a=i*Math.PI/6;made=!!spawnAnimal(kind,Math.round(player.x+Math.sin(a)*radius),Math.round(player.z+Math.cos(a)*radius));
  }
 }
 setMenuStatus('Created “'+currentWorld.name+'” · '+(gameMode==='creative'?'Creative':'Survival')+' · '+(worldType==='superflat'?'Superflat':'Normal')+'.');
 saveCurrentWorld(true);
 showNotice('World created. Press Esc to save or quit.');
}
function applySaveData(data){
 worldSpawn.x=Number(data.worldSpawn?.x)||0;worldSpawn.z=Number(data.worldSpawn?.z)||5;
 edits.clear();for(const [k,entries] of data.edits||[]){const m=new Map();for(const [i,v] of entries)m.set(i,v);edits.set(Number(k),m);}
 chests.clear();for(const [k,slots] of data.chests||[])chests.set(k,Array.isArray(slots)?slots:Array(27).fill(null));
 furnaces.clear();for(const [k,f] of data.furnaces||[])furnaces.set(k,f);
 signs.clear();for(const [k,t] of data.signs||[])signs.set(k,t);
 mapMarkers.length=0;mapMarkers.push(...(data.markers||[]));mapTiles.clear();renderMarkerList();
 cropKeys.clear();for(const k of data.cropKeys||[])cropKeys.add(k);
 saplingKeys.clear();for(const k of data.saplingKeys||[])saplingKeys.add(k);
 caneKeys.clear();for(const k of data.caneKeys||[])caneKeys.add(k);
 villageChestKeys.clear();for(const k of data.villageChestKeys||[])villageChestKeys.add(k);
 restoreArray(hotbar,data.hotbar,9);restoreArray(inventoryItems,data.inventoryItems,36);
 restoreArray(armorSlots,data.armorSlots,4);backSlot=data.backSlot||null;fairyFlightTimer=0;restoreArray(craftSlots,data.craftSlots,4);tableCraftSlots.fill(null);
 selected=Math.max(0,Math.min(8,Number(data.selected)||0));
 const sp=data.player||{};
 Object.assign(player,{x:Number.isFinite(Number(sp.x))?Number(sp.x):0,z:Number.isFinite(Number(sp.z))?Number(sp.z):5,feet:Number.isFinite(Number(sp.feet))?Number(sp.feet):20,vy:0,grounded:false});
 yaw=Number(data.yaw)||0;pitch=Math.max(-Math.PI/2+.01,Math.min(Math.PI/2-.01,Number(data.pitch)||0));
 dayTime=Number.isFinite(data.dayTime)?data.dayTime:.2;dayNumber=Number(data.dayNumber)||1;
 bedSpawn=data.bedSpawn||null;
 Object.assign(survival,{health:20,hunger:20,stamina:100,xp:0,xpLevel:0,dead:false,exhausted:false,sprinting:false,starve:0,regen:0,attackCooldown:0,eatCooldown:0},data.survival||{});
 if(survival.health<=0){survival.health=20;survival.dead=false;}
 survival.fallPeak=player.feet;
}
function loadWorldById(id){
 mpDisconnect();
 const metas=worldMetas(),meta=metas.find(w=>w.id===id);
 const data=readWorldData(id);
 if(!meta||!data){setMenuStatus('That saved world could not be loaded.');return false;}
 currentWorld=meta;worldSeed=Number(meta.seedNum)||0;
 gameMode=meta.gameMode||data.gameMode||'survival';worldType=meta.worldType||data.worldType||'normal';creativeFlying=false;
 resetWorldState();
 applySaveData(data);
 seedSpawnChunks(player.x,player.z);
 updateChunks(true);
 if(collides(player.x,player.feet,player.z)||player.feet<MIN_Y){const s=safeSpawnNear(worldSpawn.x,worldSpawn.z,10);if(s)Object.assign(player,s,{vy:0,grounded:false});}
 waterSimActive=true;
 finishEnteringWorld();
 for(const it of [data.cursorItem,...((data.tableCraftSlots||[]).filter(Boolean))])if(it)addItem(it.type,it.count,it);
 setMenuStatus('Loaded “'+meta.name+'”.');
 return true;
}
function saveCurrentWorld(silent=false){
 if(currentWorld&&currentWorld.mp){if(!silent)showNotice('Multiplayer worlds are kept on the server.');return false;}
 if(!inGame||!started||!currentWorld)return false;
 try{
  const data={
   version:1,seedNum:worldSeed,worldType,gameMode,worldSpawn:{x:worldSpawn.x,z:worldSpawn.z},
   player:{x:player.x,z:player.z,feet:player.feet},yaw,pitch,dayTime,dayNumber,bedSpawn,
   survival:{health:survival.health,hunger:survival.hunger,stamina:survival.stamina,xp:survival.xp,xpLevel:survival.xpLevel},
   selected,hotbar,inventoryItems,armorSlots,backSlot,craftSlots,tableCraftSlots,cursorItem,
   edits:[...edits].map(([k,m])=>[k,[...m]]),
   chests:[...chests].map(([k,v])=>[k,v]),
   furnaces:[...furnaces].map(([k,v])=>[k,v]),
   signs:[...signs],markers:mapMarkers,
   cropKeys:[...cropKeys],saplingKeys:[...saplingKeys],caneKeys:[...caneKeys],villageChestKeys:[...villageChestKeys]
  };
  saveWorldData(currentWorld.id,data);
  const list=worldMetas(),idx=list.findIndex(w=>w.id===currentWorld.id);
  currentWorld.updated=Date.now();currentWorld.gameMode=gameMode;currentWorld.worldType=worldType;
  if(idx>=0)list[idx]=currentWorld;else list.push(currentWorld);
  writeWorldMetas(list);
  lastSaveTime=currentWorld.updated;
  if(!silent){setMenuStatus('World saved at '+new Date(lastSaveTime).toLocaleTimeString()+'.');showNotice('World saved.');}
  return true;
 }catch(e){
  setMenuStatus('Save failed: browser storage may be full.');showNotice('Save failed — storage may be full.');
  return false;
 }
}
function renderWorldList(){
 const list=worldMetas().sort((a,b)=>(b.updated||0)-(a.updated||0));
 worldListEl.innerHTML='';
 if(!list.length){const p=document.createElement('p');p.textContent='No saved worlds yet. Create one below.';worldListEl.appendChild(p);return;}
 for(const meta of list){
  const card=document.createElement('div');card.className='worldCard';
  const title=document.createElement('strong');title.textContent=meta.name||'World';
  const info=document.createElement('small');info.textContent=(meta.gameMode==='creative'?'Creative':'Survival')+' · '+(meta.worldType==='superflat'?'Superflat':'Normal')+' · Seed: '+(meta.seedLabel??meta.seedNum)+' · '+new Date(meta.updated||meta.created||Date.now()).toLocaleString();
  const actions=document.createElement('div');actions.className='menuActions';
  const play=document.createElement('button');play.className='menuBtn primary';play.textContent='Play';play.onclick=()=>loadWorldById(meta.id);
  const del=document.createElement('button');del.className='menuBtn danger';del.textContent='Delete';del.onclick=()=>{
   if(!confirm('Delete world “'+(meta.name||'World')+'”? This cannot be undone.'))return;
   writeWorldMetas(worldMetas().filter(w=>w.id!==meta.id));
   try{localStorage.removeItem('mc-classic-world-'+meta.id)}catch{}
   if(currentWorld?.id===meta.id)currentWorld=null;
   renderWorldList();setMenuStatus('World deleted.');
  };
  actions.append(play,del);card.append(title,info,actions);worldListEl.appendChild(card);
 }
}
function openMenu(paused){
 if(paused){
  if(survival.dead||sleepTimer>0)return;
  closeAllPanelsForMenu();pauseInput();if(pointerLocked)document.exitPointerLock();
  menuOpen=true;started=true;inGame=true;
  saveCurrentWorld(true);
  menuSubtitle.textContent='Paused. Save, resume, or return to the world menu.';
  menuActions.style.display='flex';worldListEl.style.display='none';createWorldForm.style.display='none';
 }else{
  menuOpen=true;started=false;inGame=false;
  menuSubtitle.textContent='Create a world or continue a saved one.';
  menuActions.style.display='none';worldListEl.style.display='grid';createWorldForm.style.display='flex';
 }
 menuEl.classList.remove('hidden');document.body.classList.add('menu-open');
 document.getElementById('menuHome').style.display='block';document.getElementById('settingsPage').style.display='none';
 start.style.display='none';document.getElementById('deathScreen').style.display='none';
 renderWorldList();setMenuStatus('');
}
function resumeGame(){
 if(!started||!inGame)return;
 menuOpen=false;menuEl.classList.add('hidden');document.body.classList.remove('menu-open');
 updateStartOverlay();
 if(!touchMode){const req=renderer.domElement.requestPointerLock();if(req?.catch)req.catch(()=>{});}
}
function quitToMenu(){
 mpDisconnect();
 if(inGame)saveCurrentWorld(true);
 started=false;inGame=false;menuOpen=true;pauseInput();
 if(pointerLocked)document.exitPointerLock();
 openMenu(false);
}
document.getElementById('resumeButton').addEventListener('click',resumeGame);
(()=>{const pr=mpPrefs();if(pr.url)document.getElementById('mpServer').value=pr.url;if(pr.name)document.getElementById('mpName').value=pr.name;
 document.getElementById('mpJoin').addEventListener('click',mpJoinClick);})();
document.getElementById('saveButton').addEventListener('click',()=>saveCurrentWorld(false));
document.getElementById('saveQuitButton').addEventListener('click',()=>{saveCurrentWorld(true);quitToMenu()});
createWorldForm.addEventListener('submit',e=>{
 e.preventDefault();const name=newWorldName.value.trim()||'New World',seed=newWorldSeed.value;
 setMenuStatus('Generating world…');
 createNewWorld(name,seed);newWorldName.value='';newWorldSeed.value='';
});
document.getElementById('settingsButton').addEventListener('click',()=>{document.getElementById('menuHome').style.display='none';document.getElementById('settingsPage').style.display='block';});
document.getElementById('settingsBackButton').addEventListener('click',()=>{document.getElementById('settingsPage').style.display='none';document.getElementById('menuHome').style.display='block';});
window.addEventListener('beforeunload',()=>{if(inGame&&started&&!survival.dead)saveCurrentWorld(true)});
setInterval(()=>{if(inGame&&started&&!survival.dead&&!menuOpen)saveCurrentWorld(true)},30000);

